import type { AxisId } from './instrument'

/**
 * Polyaxis v2.2 question bank (generated from the canonical bank in
 * supabase/fresh_install.sql). v2.2 keeps the 300 v2.1
 * comprehension-revised items unchanged and appends 50 controversy-stress
 * items (ids 301-350): overt, neutrally worded questions on abortion,
 * economic systems, extreme wealth, reparations, firearms, gender
 * identity, immigration enforcement, capital punishment, nuclear first
 * use, and similar high-conflict topics. The new items are primary-only
 * (no tradeoff links), so the 48 collision scenarios across 24 mirrored
 * pairs are unchanged. Used only as the seed fallback (seedQuestions);
 * the live survey always reads the database.
 */
export type BankItem = {
  id: number
  order: number
  axis: AxisId
  key: 1 | -1
  text: string
  question_type: 'conceptual' | 'applied'
  weight: number
  educational_content?: string
}

export const BANK_VERSION = 'v2.2'

export const BANK_ITEMS: BankItem[] = [
  { id: 1, order: 1, axis: "C1", key: -1, text: "Markets do not reliably provide essential services fairly without direct public control. In other words, markets alone may leave essential services unfair or unavailable, so government ownership or control may be needed.", question_type: "conceptual", weight: 1.0 },
  { id: 2, order: 2, axis: "C1", key: -1, text: "Governments should steer investment toward strategic social goals rather than leave capital allocation mainly to private investors. In other words, government should guide where major investment goes when public goals differ from what private investors would choose.", question_type: "conceptual", weight: 1.0 },
  { id: 3, order: 3, axis: "C1", key: -1, text: "Public ownership is often justified when an industry is a natural monopoly or basic necessity. In other words, public ownership can make sense when one provider naturally dominates or the service is essential.", question_type: "conceptual", weight: 1.0 },
  { id: 4, order: 4, axis: "C1", key: 1, text: "Decentralized prices usually coordinate complex economic activity better than administrative plans. In other words, prices and independent buying and selling usually organize the economy better than central planning.", question_type: "conceptual", weight: 1.0 },
  { id: 5, order: 5, axis: "C1", key: 1, text: "Competition among private providers generally improves quality and lowers costs. In other words, allowing multiple providers to compete usually benefits customers.", question_type: "conceptual", weight: 1.0 },
  { id: 6, order: 6, axis: "C1", key: 1, text: "Businesses should normally be allowed to fail when they cannot serve customers profitably. In other words, government should not routinely rescue firms that cannot remain viable.", question_type: "conceptual", weight: 1.0 },
  { id: 7, order: 7, axis: "C1", key: -1, text: "Electricity transmission and distribution should be operated as a regulated public utility rather than as competing private networks. In other words, the high-voltage grid and local delivery wires would be run by a public body or a tightly regulated monopoly instead of several companies building competing networks.", question_type: "applied", weight: 1.15, educational_content: "Assume that one integrated network is needed for reliable service, and either public ownership or regulation would still control prices and service standards." },
  { id: 8, order: 8, axis: "C1", key: -1, text: "The government should use a public development bank to direct long-term credit toward regions that private lenders consistently neglect. In other words, a public development bank is a government-backed lender created to finance long-term projects or sectors that private credit may underserve.", question_type: "applied", weight: 1.15, educational_content: "Assume that the neglected regions contain viable long-term projects that ordinary lenders systematically underfinance." },
  { id: 9, order: 9, axis: "C1", key: -1, text: "The state should take an ownership stake in domestic semiconductor production when dependence on foreign suppliers threatens national resilience. In other words, an ownership stake gives the government partial equity and influence rather than only offering a grant, loan, or tax credit.", question_type: "applied", weight: 1.15, educational_content: "Assume that dependence on foreign suppliers creates a serious resilience risk and the ownership stake is transparent and reviewable." },
  { id: 10, order: 10, axis: "C1", key: -1, text: "During a severe shortage of a life-saving medicine, the government should temporarily cap prices and allocate supplies by medical need. In other words, a temporary price cap limits the maximum legal price, while allocation rules determine who receives scarce supply.", question_type: "applied", weight: 1.15, educational_content: "Assume that the medicine shortage is severe, the price cap is temporary, and allocation by medical need can be administered fairly." },
  { id: 11, order: 11, axis: "C1", key: 1, text: "New private clinics should be allowed to compete with public hospitals when they meet the same safety and transparency standards. In other words, competition here assumes all providers must meet the same licensing, safety, and disclosure requirements.", question_type: "applied", weight: 1.15, educational_content: "Assume that public and private clinics face the same safety, reporting, and patient-access rules." },
  { id: 12, order: 12, axis: "C1", key: 1, text: "Occupational licensing should be removed when it mainly restricts entry and cannot be shown to protect public safety. In other words, occupational licensing requires government permission to enter a profession, often through education, examination, or fee requirements.", question_type: "applied", weight: 1.15, educational_content: "Assume that independent evidence shows that the licensing rule does not materially improve public safety." },
  { id: 13, order: 13, axis: "C1", key: 1, text: "A poorly managed airline should be allowed to enter bankruptcy rather than receive repeated public subsidies to preserve every route and job. In other words, bankruptcy can reorganize or liquidate a firm while applying established rules to creditors, workers, and customers.", question_type: "applied", weight: 1.15, educational_content: "Assume that ordinary bankruptcy law protects passengers, workers, and creditors and allows temporary continuity of essential routes where necessary." },
  { id: 14, order: 14, axis: "C1", key: 1, text: "Municipal broadband systems should face competition from private providers rather than receive an exclusive local monopoly. In other words, municipal broadband is internet service owned or operated by a local government.", question_type: "applied", weight: 1.15 },
  { id: 15, order: 15, axis: "C2", key: -1, text: "Reducing large inequalities should be a central aim of economic policy. In other words, reducing the gap between rich and poor should be a major policy goal.", question_type: "conceptual", weight: 1.0 },
  { id: 16, order: 16, axis: "C2", key: -1, text: "Society should guarantee everyone a decent material floor regardless of market income. In other words, everyone should be guaranteed enough resources for a basic standard of living, even without sufficient earnings.", question_type: "conceptual", weight: 1.0 },
  { id: 17, order: 17, axis: "C2", key: -1, text: "Extreme concentrations of wealth undermine equal citizenship. In other words, very large wealth gaps can make citizens unequal in political and social power.", question_type: "conceptual", weight: 1.0 },
  { id: 18, order: 18, axis: "C2", key: 1, text: "People have a strong claim to keep lawfully acquired income and property. In other words, people should normally be allowed to keep income and property they obtained legally.", question_type: "conceptual", weight: 1.0 },
  { id: 19, order: 19, axis: "C2", key: 1, text: "Unequal outcomes are acceptable when the rules are fair and opportunities are open. In other words, unequal results can be fair when the process is fair and people had genuine chances to succeed.", question_type: "conceptual", weight: 1.0 },
  { id: 20, order: 20, axis: "C2", key: 1, text: "Passing property to one's family is a legitimate extension of ownership. In other words, owners should generally be free to leave property to their families.", question_type: "conceptual", weight: 1.0 },
  { id: 21, order: 21, axis: "C2", key: -1, text: "A universal basic income funded by higher taxes on top incomes should guarantee every adult a minimum cash floor. In other words, a universal basic income is a regular cash payment provided without a work requirement or means test.", question_type: "applied", weight: 1.15 },
  { id: 22, order: 22, axis: "C2", key: -1, text: "State funding should equalize per-pupil school resources across wealthy and poor districts, even when it requires transferring local tax revenue. In other words, fiscal equalization shifts revenue so jurisdictions with different tax bases can provide more comparable services.", question_type: "applied", weight: 1.15, educational_content: "Assume that the transfer establishes a minimum resource level without preventing wealthier districts from spending additional local funds." },
  { id: 23, order: 23, axis: "C2", key: -1, text: "Long-term care for older adults and people with severe disabilities should be publicly guaranteed and financed according to ability to pay. In other words, long-term care includes ongoing help with daily living in homes, community settings, or residential facilities.", question_type: "applied", weight: 1.15 },
  { id: 24, order: 24, axis: "C2", key: -1, text: "Very large financial inheritances should face progressive taxation, with clearly defined exemptions for genuinely operating family businesses. In other words, an estate tax is assessed on transferred wealth at death; progressive rates rise with the size of the taxable estate.", question_type: "applied", weight: 1.15, educational_content: "Assume that the exemption is limited to genuine operating businesses rather than passive investment assets." },
  { id: 25, order: 25, axis: "C2", key: 1, text: "People who signed standard student loans should generally repay them rather than receive broad cancellation funded by taxpayers who did not borrow. In other words, broad cancellation forgives debt across a large class of borrowers rather than only in cases such as fraud, disability, or insolvency.", question_type: "applied", weight: 1.15, educational_content: "Assume that the loans were lawfully issued, clearly disclosed, and not affected by fraud, permanent disability, or insolvency." },
  { id: 26, order: 26, axis: "C2", key: 1, text: "Owner-occupied homes should not be subject to an annual wealth tax merely because neighborhood values have risen. In other words, an annual wealth tax is based on the value of owned assets rather than only on income or a sale.", question_type: "applied", weight: 1.15, educational_content: "Assume that the annual tax is based on the home's current value even though the owner has not sold it or received cash from the increase." },
  { id: 27, order: 27, axis: "C2", key: 1, text: "Private firms should not be required to transfer ownership shares to employees as a condition of remaining in business. In other words, mandatory employee equity would require firms to transfer part of ownership, not merely share profits or offer optional stock plans.", question_type: "applied", weight: 1.15 },
  { id: 28, order: 28, axis: "C2", key: 1, text: "A flat income tax with a generous personal exemption is fairer than progressively higher marginal tax rates. In other words, a flat tax applies one marginal rate above an exemption; a progressive system applies higher marginal rates to higher income brackets.", question_type: "applied", weight: 1.15, educational_content: "Assume that the personal exemption is high enough that low-income households owe no income tax." },
  { id: 29, order: 29, axis: "C3", key: -1, text: "Preventing serious harm can justify restrictions before an individual offense occurs. In other words, government may restrict someone before they commit a crime when there is strong evidence of serious danger.", question_type: "conceptual", weight: 1.0 },
  { id: 30, order: 30, axis: "C3", key: -1, text: "Law enforcement needs broad powers when public safety is under substantial threat. In other words, police and security agencies may need wide authority during a major threat.", question_type: "conceptual", weight: 1.0 },
  { id: 31, order: 31, axis: "C3", key: -1, text: "Maintaining public order sometimes requires limiting movement, assembly, or privacy. In other words, protecting public order can sometimes justify temporary limits on where people go, gather, or keep information private.", question_type: "conceptual", weight: 1.0 },
  { id: 32, order: 32, axis: "C3", key: 1, text: "Government should need specific evidence before restricting a peaceful person's liberty. In other words, peaceful people should not lose freedom based only on general suspicion or administrative convenience.", question_type: "conceptual", weight: 1.0 },
  { id: 33, order: 33, axis: "C3", key: 1, text: "Privacy should not be sacrificed merely because surveillance would make enforcement easier. In other words, easier enforcement is not by itself a good enough reason for government surveillance.", question_type: "conceptual", weight: 1.0 },
  { id: 34, order: 34, axis: "C3", key: 1, text: "Offensive or unpopular expression should remain legal unless it directly threatens others. In other words, speech should remain legal even when offensive unless it creates a direct threat or harm.", question_type: "conceptual", weight: 1.0 },
  { id: 35, order: 35, axis: "C3", key: -1, text: "A court should be able to order temporary inpatient treatment for a person in an acute psychotic crisis who poses a serious and immediate danger. In other words, involuntary inpatient treatment confines a person for care without consent and is normally subject to legal standards and review.", question_type: "applied", weight: 1.15, educational_content: "Assume that qualified clinicians find a serious and immediate danger, confinement is temporary, and a court promptly reviews the order." },
  { id: 36, order: 36, axis: "C3", key: -1, text: "Authorities should be able to impose a narrowly limited quarantine on people confirmed to carry a highly lethal contagious disease. In other words, quarantine restricts the movement of people exposed to or carrying an infectious disease.", question_type: "applied", weight: 1.15, educational_content: "Assume that infection is confirmed, the disease is highly lethal, the quarantine is no broader or longer than necessary, and basic needs are provided." },
  { id: 37, order: 37, axis: "C3", key: -1, text: "After several nights of organized violence, a city may impose a temporary nighttime curfew with judicial review. In other words, a curfew restricts presence in public places during specified hours and may include exemptions for work, care, and emergencies.", question_type: "applied", weight: 1.15, educational_content: "Assume that organized violence is ongoing, the curfew is temporary, essential travel is exempt, and courts can review abuses promptly." },
  { id: 38, order: 38, axis: "C3", key: -1, text: "Large public events may require universal bag screening even when there is no individualized suspicion. In other words, universal screening applies the same search procedure to all entrants rather than selecting individuals based on suspicion.", question_type: "applied", weight: 1.15, educational_content: "Assume that the same limited screening applies to every attendee and collected information is not kept for unrelated purposes." },
  { id: 39, order: 39, axis: "C3", key: 1, text: "Police should need a warrant to obtain a person's historical cellphone-location records. In other words, historical cellphone-location records can reconstruct where a device was located over time.", question_type: "applied", weight: 1.15 },
  { id: 40, order: 40, axis: "C3", key: 1, text: "Property should not be permanently seized through civil forfeiture unless its owner is convicted or the government proves the property's involvement in court. In other words, the government could not permanently take property merely because it suspects a connection to wrongdoing; a conviction or a separate court finding would be required.", question_type: "applied", weight: 1.15, educational_content: "Assume that the owner can contest the seizure before an independent court and the government bears the burden of proof." },
  { id: 41, order: 41, axis: "C3", key: 1, text: "Emergency powers should expire automatically unless the legislature affirmatively renews them after public debate. In other words, a sunset clause makes a legal power expire on a set date unless lawmakers renew it.", question_type: "applied", weight: 1.15, educational_content: "Assume that the legislature can renew the power through an ordinary public vote after reviewing current evidence." },
  { id: 42, order: 42, axis: "C3", key: 1, text: "Adults should be permitted to possess small amounts of currently illegal drugs for personal use, subject to health and age regulations. In other words, decriminalization removes criminal penalties for possession; legalization also permits regulated production or sale.", question_type: "applied", weight: 1.15 },
  { id: 43, order: 43, axis: "C4", key: -1, text: "National standards are necessary when local variation would produce unequal basic rights or services. In other words, the national government should set minimum rules when local differences would deny people basic rights or services.", question_type: "conceptual", weight: 1.0 },
  { id: 44, order: 44, axis: "C4", key: -1, text: "Large-scale problems are usually handled best by a central government with broad coordinating authority. In other words, problems affecting many regions often need one central authority to coordinate the response.", question_type: "conceptual", weight: 1.0 },
  { id: 45, order: 45, axis: "C4", key: -1, text: "Higher levels of government should prevent local decisions that impose serious costs on neighboring regions. In other words, a higher government should step in when one locality seriously harms people outside its borders.", question_type: "conceptual", weight: 1.0 },
  { id: 46, order: 46, axis: "C4", key: 1, text: "Decisions should normally be made by the smallest jurisdiction capable of handling them. In other words, decisions should stay local unless a larger government is needed to solve the problem.", question_type: "conceptual", weight: 1.0 },
  { id: 47, order: 47, axis: "C4", key: 1, text: "Regions should be free to experiment with substantially different policies. In other words, different regions should be allowed to try different policies and learn from the results.", question_type: "conceptual", weight: 1.0 },
  { id: 48, order: 48, axis: "C4", key: 1, text: "Subnational governments should retain meaningful authority that the national government cannot easily revoke. In other words, states, provinces, or regions should have protected powers that the national government cannot easily take away.", question_type: "conceptual", weight: 1.0 },
  { id: 49, order: 49, axis: "C4", key: -1, text: "National election-administration standards should govern ballot access, counting procedures, and post-election audits in every region. In other words, one national set of minimum rules would govern who gets on the ballot, how votes are counted, and how results are checked.", question_type: "applied", weight: 1.15, educational_content: "Assume that the national rules are minimum procedural standards and regions may adopt additional safeguards that do not conflict with them." },
  { id: 50, order: 50, axis: "C4", key: -1, text: "The national government should be able to approve interstate transmission lines after a uniform review, even when individual localities object. In other words, transmission lines move electricity over long distances and often cross many local jurisdictions.", question_type: "applied", weight: 1.15, educational_content: "Assume that the line serves a documented interstate need and the uniform review considers safety, environmental effects, and local alternatives." },
  { id: 51, order: 51, axis: "C4", key: -1, text: "A national disaster agency should be able to direct resources and personnel across state or provincial boundaries during a major catastrophe. In other words, central command allows one authority to allocate scarce personnel and equipment across jurisdictions.", question_type: "applied", weight: 1.15 },
  { id: 52, order: 52, axis: "C4", key: -1, text: "A national minimum school-funding floor should prevent poor regions from offering substantially fewer basic educational resources. In other words, a funding floor sets a national minimum while allowing regions to spend more.", question_type: "applied", weight: 1.15 },
  { id: 53, order: 53, axis: "C4", key: 1, text: "States or provinces should set most school curricula rather than follow a single national curriculum. In other words, curriculum authority determines required subjects, standards, and instructional frameworks.", question_type: "applied", weight: 1.15 },
  { id: 54, order: 54, axis: "C4", key: 1, text: "Municipalities should control zoning and housing density unless their decisions create clearly demonstrated harms outside their borders. In other words, zoning regulates land uses, building types, and development density.", question_type: "applied", weight: 1.15 },
  { id: 55, order: 55, axis: "C4", key: 1, text: "Indigenous or tribal governments should have primary authority over land use and natural resources within their recognized territories. In other words, legally recognized Indigenous or tribal governments would make the first decision about land and resources in their own territories.", question_type: "applied", weight: 1.15, educational_content: "Assume that the territory and the Indigenous or tribal government's governing authority are legally recognized." },
  { id: 56, order: 56, axis: "C4", key: 1, text: "Regions should be free to adopt different tax and social-policy models so voters can compare real alternatives. In other words, policy experimentation allows jurisdictions to test different approaches under comparable national rules.", question_type: "applied", weight: 1.15 },
  { id: 57, order: 57, axis: "C5", key: -1, text: "Longstanding traditions often contain social knowledge that reformers underestimate. In other words, customs that have lasted a long time may contain practical wisdom that is not obvious to reformers.", question_type: "conceptual", weight: 1.0 },
  { id: 58, order: 58, axis: "C5", key: -1, text: "Stable family and civic institutions are more important than constant adaptation to changing preferences. In other words, preserving stable families and civic organizations can matter more than continually changing them to fit new preferences.", question_type: "conceptual", weight: 1.0 },
  { id: 59, order: 59, axis: "C5", key: -1, text: "Rapid cultural change can weaken the shared norms needed for social trust. In other words, very fast cultural change can weaken the shared expectations that help people trust one another.", question_type: "conceptual", weight: 1.0 },
  { id: 60, order: 60, axis: "C5", key: 1, text: "Social norms should change when inherited roles unnecessarily restrict people's lives. In other words, traditions should be changed when they limit people without a strong reason.", question_type: "conceptual", weight: 1.0 },
  { id: 61, order: 61, axis: "C5", key: 1, text: "Institutions should revise traditions that exclude people without sufficient justification. In other words, institutions should revise customs that unfairly exclude people.", question_type: "conceptual", weight: 1.0 },
  { id: 62, order: 62, axis: "C5", key: 1, text: "New family and cultural forms can be as socially valuable as inherited ones. In other words, newer ways of forming families and communities can be just as valuable as traditional ones.", question_type: "conceptual", weight: 1.0 },
  { id: 63, order: 63, axis: "C5", key: -1, text: "Public schools should emphasize a shared national language even while offering additional support to students who speak other languages at home. In other words, a shared-language policy can coexist with transitional or supplemental multilingual support.", question_type: "applied", weight: 1.15 },
  { id: 64, order: 64, axis: "C5", key: -1, text: "Communities should generally retain historic monuments and civic rituals while adding context rather than removing them when values change. In other words, contextualization adds interpretation or counter-perspectives without removing the original object or ritual.", question_type: "applied", weight: 1.15 },
  { id: 65, order: 65, axis: "C5", key: -1, text: "When dependent children are involved, the law should require a waiting period and mediation before a no-fault divorce is finalized, except in cases of abuse or abandonment. In other words, parents could still end a marriage without proving fault, but they would normally complete a waiting period and mediation first when children depend on them.", question_type: "applied", weight: 1.15, educational_content: "Assume that mediation concerns practical arrangements and cannot force reconciliation; either spouse can still obtain the divorce after the waiting period." },
  { id: 66, order: 66, axis: "C5", key: -1, text: "Public institutions may preserve longstanding religiously rooted holidays and ceremonies when participation is voluntary. In other words, a religiously rooted civic practice may retain historical meaning even when formal participation is optional.", question_type: "applied", weight: 1.15 },
  { id: 67, order: 67, axis: "C5", key: 1, text: "Adoption eligibility should be based on caregiving ability rather than marital status, sexual orientation, or whether a household fits a traditional family model. In other words, adoption agencies would judge whether applicants can provide a safe and stable home, not whether they fit a preferred family structure.", question_type: "applied", weight: 1.15, educational_content: "Assume that all applicants meet the same standards for safety, stability, and caregiving ability." },
  { id: 68, order: 68, axis: "C5", key: 1, text: "Adults should have access to no-fault divorce without proving misconduct by a spouse. In other words, no-fault divorce permits a marriage to end without proving adultery, abandonment, or another legal wrong.", question_type: "applied", weight: 1.15 },
  { id: 69, order: 69, axis: "C5", key: 1, text: "Official civic ceremonies should be revised over time to include secular and minority traditions rather than preserve one inherited form. In other words, inclusive redesign changes shared public ceremonies rather than merely adding private alternatives.", question_type: "applied", weight: 1.15 },
  { id: 70, order: 70, axis: "C5", key: 1, text: "Schools should teach that family and household arrangements have changed across history without presenting one current model as universally preferred. In other words, the question concerns descriptive and normative framing, not whether schools must endorse every arrangement.", question_type: "applied", weight: 1.15 },
  { id: 71, order: 71, axis: "C6", key: -1, text: "People legitimately owe stronger duties to family, community, and fellow citizens than to strangers. In other words, people may reasonably owe more to those close to them or in their political community than to people everywhere.", question_type: "conceptual", weight: 1.0 },
  { id: 72, order: 72, axis: "C6", key: -1, text: "Shared membership and contribution can create special claims on common resources. In other words, contributing to and belonging to a community can justify receiving some benefits before nonmembers.", question_type: "conceptual", weight: 1.0 },
  { id: 73, order: 73, axis: "C6", key: -1, text: "A community may preserve benefits for its members without treating outsiders as morally inferior. In other words, a community can favor its own members without claiming outsiders have less human worth.", question_type: "conceptual", weight: 1.0 },
  { id: 74, order: 74, axis: "C6", key: 1, text: "A person's nationality, ancestry, or distance should not reduce the moral weight of their basic needs. In other words, a person's needs matter equally even if they live far away or belong to another nation or ancestry.", question_type: "conceptual", weight: 1.0 },
  { id: 75, order: 75, axis: "C6", key: 1, text: "Aid should be allocated primarily according to need rather than group membership. In other words, help should go first to those in greatest need rather than to members of a preferred group.", question_type: "conceptual", weight: 1.0 },
  { id: 76, order: 76, axis: "C6", key: 1, text: "Public institutions should apply the same basic rules across ethnic, religious, and national lines. In other words, government should apply the same basic standards regardless of ethnicity, religion, or nationality.", question_type: "conceptual", weight: 1.0 },
  { id: 77, order: 77, axis: "C6", key: -1, text: "When public housing is scarce, long-term local residents may receive priority among applicants with comparable levels of need. In other words, a residency preference ranks otherwise similar applicants by length or continuity of local residence.", question_type: "applied", weight: 1.15, educational_content: "Assume that applicants being compared have genuinely similar levels of housing need." },
  { id: 78, order: 78, axis: "C6", key: -1, text: "Veterans may receive a modest preference in public hiring because military service creates a special reciprocal obligation. In other words, a modest preference can affect ranking without guaranteeing selection over substantially better-qualified applicants.", question_type: "applied", weight: 1.15, educational_content: "Assume that the preference is modest and does not automatically defeat substantially better-qualified applicants." },
  { id: 79, order: 79, axis: "C6", key: -1, text: "A locally funded mutual-aid program may reserve some benefits for people who have contributed to it over time. In other words, mutual-aid programs pool contributions among members and distribute benefits under agreed rules.", question_type: "applied", weight: 1.15 },
  { id: 80, order: 80, axis: "C6", key: -1, text: "A diaspora charity may reasonably prioritize members of its own dispersed community before assisting unrelated groups. In other words, a diaspora is a community dispersed from an ancestral homeland while maintaining shared ties.", question_type: "applied", weight: 1.15, educational_content: "Assume that the organization is privately funded and is not distributing a government benefit." },
  { id: 81, order: 81, axis: "C6", key: 1, text: "Refugee admissions should prioritize vulnerability and danger rather than cultural similarity to the receiving country. In other words, vulnerability criteria can include persecution risk, medical need, family separation, and immediate danger.", question_type: "applied", weight: 1.15 },
  { id: 82, order: 82, axis: "C6", key: 1, text: "After domestic high-risk groups are protected, surplus vaccines should be distributed internationally according to medical need. In other words, the domestic threshold is satisfied before the question turns to allocation of remaining supply.", question_type: "applied", weight: 1.15, educational_content: "Assume that the country's highest-risk residents have already received reasonable protection and the remaining doses would otherwise be unused or delayed." },
  { id: 83, order: 83, axis: "C6", key: 1, text: "Public hiring and services should apply the same eligibility rules regardless of an applicant's ethnicity, religion, or ancestry. In other words, uniform eligibility does not preclude accommodations tied to disability, language access, or other functional needs.", question_type: "applied", weight: 1.15 },
  { id: 84, order: 84, axis: "C6", key: 1, text: "Humanitarian aid should be allocated where it prevents the most severe suffering rather than primarily to allied countries. In other words, this contrasts humanitarian need with strategic or alliance-based allocation.", question_type: "applied", weight: 1.15 },
  { id: 85, order: 85, axis: "C7", key: -1, text: "Domestic voters should retain final authority over laws that govern them. In other words, voters within a country should have the final say over the laws they must follow.", question_type: "conceptual", weight: 1.0 },
  { id: 86, order: 86, axis: "C7", key: -1, text: "International agreements should not permanently bind a country against sustained democratic opposition. In other words, a country should be able to leave an international commitment that its population persistently rejects.", question_type: "conceptual", weight: 1.0 },
  { id: 87, order: 87, axis: "C7", key: -1, text: "Nations need the ability to act unilaterally when common institutions fail. In other words, countries must sometimes act on their own when international organizations cannot respond.", question_type: "conceptual", weight: 1.0 },
  { id: 88, order: 88, axis: "C7", key: 1, text: "Countries should accept binding common rules when unilateral action cannot solve shared problems. In other words, countries should accept enforceable shared rules when no country can solve the problem alone.", question_type: "conceptual", weight: 1.0 },
  { id: 89, order: 89, axis: "C7", key: 1, text: "Some sovereignty should be pooled in institutions capable of enforcing international commitments. In other words, countries should transfer some decision-making power to international institutions so common commitments can be enforced.", question_type: "conceptual", weight: 1.0 },
  { id: 90, order: 90, axis: "C7", key: 1, text: "International courts and regulators can legitimately constrain national governments. In other words, international bodies may legitimately overrule or limit a national government's choices in some areas.", question_type: "conceptual", weight: 1.0 },
  { id: 91, order: 91, axis: "C7", key: -1, text: "A country should retain an independent currency rather than join a monetary union that transfers interest-rate policy to a shared central bank and includes common fiscal rules. In other words, joining the union would move routine interest-rate decisions to a shared central bank and would also require compliance with agreed limits on national budgeting.", question_type: "applied", weight: 1.15, educational_content: "Assume that the monetary union has one shared central bank and expressly agreed fiscal rules; leaving those rules would require leaving or renegotiating the union." },
  { id: 92, order: 92, axis: "C7", key: -1, text: "National food-safety rules should not be weakened merely because an international trade tribunal considers them a barrier to commerce. In other words, a trade body should not force a country to weaken a safety rule merely because the rule makes imported goods harder to sell.", question_type: "applied", weight: 1.15, educational_content: "Assume that the national food-safety rule is supported by credible evidence and is not disguised protectionism." },
  { id: 93, order: 93, axis: "C7", key: -1, text: "Foreign purchases of strategically important infrastructure should be subject to national-security screening even when treaties favor open investment. In other words, the government would review foreign purchases of ports, power systems, communications networks, or similar assets for security risks.", question_type: "applied", weight: 1.15, educational_content: "Assume that the infrastructure is genuinely important to national security or resilience and the review applies clear published standards." },
  { id: 94, order: 94, axis: "C7", key: -1, text: "A government should be able to withdraw from a treaty when its voters reject the continuing obligations. In other words, treaties often include withdrawal procedures and notice periods.", question_type: "applied", weight: 1.15 },
  { id: 95, order: 95, axis: "C7", key: 1, text: "Countries should accept a common minimum corporate-tax floor to reduce profit shifting between jurisdictions. In other words, a minimum corporate-tax floor reduces incentives to book profits in very low-tax jurisdictions.", question_type: "applied", weight: 1.15 },
  { id: 96, order: 96, axis: "C7", key: 1, text: "Member states in a regional union should share responsibility for asylum claims according to population and capacity. In other words, countries in the union would divide responsibility for asylum seekers using a common formula based on population and available resources.", question_type: "applied", weight: 1.15, educational_content: "Assume that the regional union has legal authority to enforce the allocation formula and provides funding for the assigned responsibilities." },
  { id: 97, order: 97, axis: "C7", key: 1, text: "Cross-border supply chains should be subject to enforceable international labor standards. In other words, enforceable standards may use inspections, complaints, trade consequences, or corporate liability.", question_type: "applied", weight: 1.15 },
  { id: 98, order: 98, axis: "C7", key: 1, text: "Countries should accept binding international rules for reporting dangerous disease outbreaks and sharing pathogen data. In other words, pathogen data can support diagnosis, vaccines, and outbreak tracking but may carry economic or security concerns.", question_type: "applied", weight: 1.15 },
  { id: 99, order: 99, axis: "C8", key: -1, text: "New technologies should face strong precaution when their harms could be irreversible. In other words, society should be very cautious before using a technology that could cause permanent harm.", question_type: "conceptual", weight: 1.0 },
  { id: 100, order: 100, axis: "C8", key: -1, text: "Resilience and human control are often more important than maximum technological efficiency. In other words, systems that remain safe and controllable during failure can matter more than getting the greatest efficiency.", question_type: "conceptual", weight: 1.0 },
  { id: 101, order: 101, axis: "C8", key: -1, text: "Some technologies create risks that society cannot responsibly manage after deployment. In other words, some technologies may be too dangerous to release because their risks cannot be controlled afterward.", question_type: "conceptual", weight: 1.0 },
  { id: 102, order: 102, axis: "C8", key: 1, text: "Innovation should generally proceed unless there is clear evidence of serious harm. In other words, new technology should usually be allowed unless strong evidence shows it is seriously dangerous.", question_type: "conceptual", weight: 1.0 },
  { id: 103, order: 103, axis: "C8", key: 1, text: "Technological progress can solve constraints that political redistribution alone cannot. In other words, innovation can create more resources or capabilities instead of only redistributing what already exists.", question_type: "conceptual", weight: 1.0 },
  { id: 104, order: 104, axis: "C8", key: 1, text: "Society should accept some disruption and uncertainty to gain the long-term benefits of innovation. In other words, society should tolerate some short-term disruption and risk to obtain larger future benefits from innovation.", question_type: "conceptual", weight: 1.0 },
  { id: 105, order: 105, axis: "C8", key: -1, text: "Heritable editing of human embryos should remain prohibited until safety, consent across generations, and governance problems are substantially resolved. In other words, changes to an embryo's DNA could pass to later generations, so deployment would wait until safety and governance questions are much more settled.", question_type: "applied", weight: 1.15, educational_content: "Assume that current evidence does not yet resolve major safety, consent, and governance concerns and the prohibition can be reconsidered as evidence improves." },
  { id: 106, order: 106, axis: "C8", key: -1, text: "Critical infrastructure should retain manual and offline backups even when full automation would be cheaper and more efficient. In other words, offline and manual backups reduce dependence on connected automated systems during cyberattack or system failure.", question_type: "applied", weight: 1.15 },
  { id: 107, order: 107, axis: "C8", key: -1, text: "Routine police use of facial recognition in public spaces should be prohibited until accuracy, bias, and abuse risks are demonstrably controlled. In other words, facial-recognition systems compare images to stored templates and can produce false matches that vary across populations.", question_type: "applied", weight: 1.15, educational_content: "Assume that accuracy and abuse risks have not yet been brought within independently verified limits." },
  { id: 108, order: 108, axis: "C8", key: -1, text: "Large outdoor geoengineering experiments should require approval from a treaty-based international body and strong evidence that any harm can be reversed. In other words, countries participating in a formal international agreement would have to approve the experiment before it could alter shared climate systems.", question_type: "applied", weight: 1.15, educational_content: "Assume that the authorizing body is established by treaty, participating countries share the affected climate risk, and emergency small-scale laboratory work remains possible." },
  { id: 109, order: 109, axis: "C8", key: 1, text: "Cities should deploy autonomous buses once independent evidence shows they are safer than human-driven fleets. In other words, autonomous buses operate without a human driver but may still use remote supervision and defined routes.", question_type: "applied", weight: 1.15, educational_content: "Assume that independent evidence shows the buses are safer overall, routes are suitable, and a human can intervene during emergencies." },
  { id: 110, order: 110, axis: "C8", key: 1, text: "Gene-edited crops should be approved when they pass the same evidence-based safety standards as conventionally bred crops. In other words, gene editing changes selected DNA sequences and differs from adding genes from unrelated organisms.", question_type: "applied", weight: 1.15, educational_content: "Assume that gene-edited and conventionally bred crops are judged under equally demanding standards based on their actual traits and risks." },
  { id: 111, order: 111, axis: "C8", key: 1, text: "Nuclear power should be expanded when modern designs can meet transparent safety and waste-management requirements. In other words, nuclear expansion can include existing reactor life extension, new large reactors, or smaller modular designs.", question_type: "applied", weight: 1.15, educational_content: "Assume that the projects meet enforceable safety, waste, security, and decommissioning requirements and their costs are transparently compared with alternatives." },
  { id: 112, order: 112, axis: "C8", key: 1, text: "Clinicians should be allowed to use validated AI diagnostic systems with human oversight rather than wait for decades of additional experience. In other words, a diagnostic AI estimates conditions from clinical data; human oversight retains a professional responsible for the final decision.", question_type: "applied", weight: 1.15, educational_content: "Assume that the AI has been independently validated for the relevant patients and a licensed clinician remains responsible for the final decision." },
  { id: 113, order: 113, axis: "C9", key: -1, text: "Environmental protection is ultimately justified by its contribution to human well-being. In other words, nature deserves protection mainly because healthy environments benefit people.", question_type: "conceptual", weight: 1.0 },
  { id: 114, order: 114, axis: "C9", key: -1, text: "Human livelihoods should usually take priority when they directly conflict with ecological preservation. In other words, jobs, food, housing, and other human needs should usually come before preserving ecosystems unchanged.", question_type: "conceptual", weight: 1.0 },
  { id: 115, order: 115, axis: "C9", key: -1, text: "Nature may be responsibly transformed to meet important human needs. In other words, people may alter natural environments when doing so meets important human needs responsibly.", question_type: "conceptual", weight: 1.0 },
  { id: 116, order: 116, axis: "C9", key: 1, text: "Species and ecosystems have value independent of their usefulness to people. In other words, plants, animals, species, and ecosystems matter morally even when they provide no direct benefit to people.", question_type: "conceptual", weight: 1.0 },
  { id: 117, order: 117, axis: "C9", key: 1, text: "Future generations and nonhuman life create moral duties for people living today. In other words, people today owe duties to future humans and to other living beings.", question_type: "conceptual", weight: 1.0 },
  { id: 118, order: 118, axis: "C9", key: 1, text: "Some natural places should remain undeveloped even when development would produce substantial economic benefits. In other words, some places should be protected from development even when development would create major economic gains.", question_type: "conceptual", weight: 1.0 },
  { id: 119, order: 119, axis: "C9", key: -1, text: "A renewable-energy transmission line may cross already disturbed habitat when it is necessary to provide reliable low-carbon power to large populations. In other words, the project could use land that is already damaged if that route is genuinely needed to deliver reliable low-carbon electricity.", question_type: "applied", weight: 1.15, educational_content: "Assume that the selected route is necessary after serious review of lower-impact alternatives and the habitat is already substantially altered." },
  { id: 120, order: 120, axis: "C9", key: -1, text: "Predators that repeatedly kill livestock may be lethally controlled when nonlethal measures have failed. In other words, nonlethal measures can include fencing, guard animals, relocation, and compensation.", question_type: "applied", weight: 1.15 },
  { id: 121, order: 121, axis: "C9", key: -1, text: "Housing may be built on degraded habitat if independent review confirms that developers will restore genuinely comparable habitat elsewhere and prevent a net increase in pollution. In other words, development would be allowed only if outside reviewers confirm that equivalent habitat will actually be restored and overall pollution will not increase.", question_type: "applied", weight: 1.15, educational_content: "Assume that independent reviewers verify ecological equivalence, restoration is funded before development, and failure triggers enforceable remedies." },
  { id: 122, order: 122, axis: "C9", key: -1, text: "Coastal flood defenses for dense communities should take priority over preserving every natural shoreline in its existing form. In other words, flood defenses can include seawalls, barriers, elevation, dunes, wetlands, and managed retreat.", question_type: "applied", weight: 1.15, educational_content: "Assume that the community faces a serious flood risk and less damaging measures cannot provide adequate protection at reasonable cost." },
  { id: 123, order: 123, axis: "C9", key: 1, text: "Farming practices that cause severe, avoidable animal suffering should be phased out even if meat becomes more expensive. In other words, animal-welfare regulation can address confinement, handling, transport, and slaughter practices.", question_type: "applied", weight: 1.15 },
  { id: 124, order: 124, axis: "C9", key: 1, text: "Mining should be denied in an intact watershed whose ecological functions cannot realistically be replaced. In other words, mining would be refused where the connected river, groundwater, and habitat system cannot realistically be recreated elsewhere.", question_type: "applied", weight: 1.15, educational_content: "Assume that independent evidence shows that the watershed's functions are critical and cannot realistically be replaced through restoration elsewhere." },
  { id: 125, order: 125, axis: "C9", key: 1, text: "Governments should restore wetlands and floodplains even when doing so removes some land from future development. In other words, wetlands and floodplains can reduce floods, filter water, and support habitat.", question_type: "applied", weight: 1.15 },
  { id: 126, order: 126, axis: "C9", key: 1, text: "Groundwater extraction should be limited when continued pumping would irreversibly damage rivers, springs, or dependent ecosystems. In other words, groundwater pumping can reduce connected surface flows and permanently compact aquifers.", question_type: "applied", weight: 1.15, educational_content: "Assume that continued pumping is projected to cause irreversible damage and users receive reasonable time and support to adapt." },
  { id: 127, order: 127, axis: "C10", key: -1, text: "Some actions are objectively wrong regardless of what any culture or majority believes. In other words, at least some actions are wrong even if every society approves of them.", question_type: "conceptual", weight: 1.0 },
  { id: 128, order: 128, axis: "C10", key: -1, text: "Moral truth is not created by social approval or historical circumstance. In other words, moral truth does not become true merely because a society accepts it or because it fits a particular era.", question_type: "conceptual", weight: 1.0 },
  { id: 129, order: 129, axis: "C10", key: -1, text: "Universal principles can legitimately be used to judge inherited customs. In other words, broad moral rules can be used to criticize traditions, even when those traditions are old and widely accepted.", question_type: "conceptual", weight: 1.0 },
  { id: 130, order: 130, axis: "C10", key: 1, text: "Moral standards are substantially shaped by culture and historical experience. In other words, what a society considers right or wrong is partly formed by its culture and history, not only discovered independently.", question_type: "conceptual", weight: 1.0 },
  { id: 131, order: 131, axis: "C10", key: 1, text: "There is no fully neutral standpoint outside human practices from which all moral disputes can be settled. In other words, no one can judge morality from a completely culture-free and history-free point of view.", question_type: "conceptual", weight: 1.0 },
  { id: 132, order: 132, axis: "C10", key: 1, text: "Societies can create new moral standards as their understanding and circumstances change. In other words, societies can develop genuinely new ideas of right and wrong rather than only uncover timeless rules that already existed.", question_type: "conceptual", weight: 1.0 },
  { id: 133, order: 133, axis: "C10", key: -1, text: "Forced marriage is wrong even when families and local custom strongly approve of it. In other words, forced marriage lacks the free and ongoing consent of at least one person.", question_type: "applied", weight: 1.15, educational_content: "Assume that at least one person lacks free and continuing consent, regardless of family approval." },
  { id: 134, order: 134, axis: "C10", key: -1, text: "A prison should prohibit prolonged solitary confinement for nonviolent rule violations even when most citizens believe harsh isolation is necessary for order. In other words, the rule would set a moral limit on isolation even when the punishment is lawful, traditional, and publicly popular.", question_type: "applied", weight: 1.15, educational_content: "Assume that the isolation is prolonged, the violation is nonviolent, and safer disciplinary methods are available." },
  { id: 135, order: 135, axis: "C10", key: -1, text: "Deliberately targeting civilians in war is wrong regardless of the cause being defended. In other words, the principle of distinction requires separating military targets from civilians.", question_type: "applied", weight: 1.15, educational_content: "Assume that the civilians are deliberately selected as targets rather than harmed incidentally during an otherwise lawful attack." },
  { id: 136, order: 136, axis: "C10", key: -1, text: "Employers should have to meet a universal minimum safety standard even when strict enforcement would close factories that provide scarce local jobs. In other words, the same basic workplace-safety rule would apply across countries even when compliance causes serious local economic costs.", question_type: "applied", weight: 1.15, educational_content: "Assume that the safety standard prevents a substantial risk of serious injury, applies equally across countries, and transition assistance has been considered." },
  { id: 137, order: 137, axis: "C10", key: 1, text: "Societies may legitimately adopt different laws on assisted dying because ideas about dignity and obligation are partly shaped by culture. In other words, different societies could reach different legitimate answers about assisted dying because their ideas of dignity and family duty differ.", question_type: "applied", weight: 1.15, educational_content: "Assume that the adults are competent, acting voluntarily, and protected by clear safeguards against coercion and abuse." },
  { id: 138, order: 138, axis: "C10", key: 1, text: "There is no single objectively correct model for how extended families should divide long-term caregiving responsibilities. In other words, there may be several legitimate ways for relatives to share elder care, rather than one arrangement that is morally correct everywhere.", question_type: "applied", weight: 1.15 },
  { id: 139, order: 139, axis: "C10", key: 1, text: "Public policy should allow substantial moral disagreement about gestational surrogacy when the adults consent and evidence of serious harm is uncertain. In other words, the law would leave room for consenting adults to use gestational surrogacy while societies continue to disagree morally about it.", question_type: "applied", weight: 1.15, educational_content: "Assume that the adults give informed consent, payment and parentage rules are clear, and reliable evidence of serious harm remains uncertain." },
  { id: 140, order: 140, axis: "C10", key: 1, text: "Schools should present major ethical controversies as disputes shaped by different traditions rather than teach that one framework has settled every issue. In other words, schools would explain the leading moral traditions and their disagreements instead of presenting one theory as having resolved every controversy.", question_type: "applied", weight: 1.15 },
  { id: 141, order: 141, axis: "C11", key: -1, text: "A coherent moral framework should be able to rank competing values in every case. In other words, one consistent moral system should ultimately be able to decide which value comes first in any conflict.", question_type: "conceptual", weight: 1.0 },
  { id: 142, order: 142, axis: "C11", key: -1, text: "Even difficult moral conflicts have a best answer in principle. In other words, even when every option has costs, there is still one morally best answer in principle.", question_type: "conceptual", weight: 1.0 },
  { id: 143, order: 143, axis: "C11", key: -1, text: "Public institutions need a stable hierarchy of values rather than case-by-case balancing. In other words, public institutions should use a consistent ordering of values instead of weighing them differently in each case.", question_type: "conceptual", weight: 1.0 },
  { id: 144, order: 144, axis: "C11", key: 1, text: "Several values can be genuine and important without being reducible to one master principle. In other words, values such as liberty, equality, loyalty, and compassion may all matter without one rule always deciding between them.", question_type: "conceptual", weight: 1.0 },
  { id: 145, order: 145, axis: "C11", key: 1, text: "Reasonable people can continue to disagree even when they share the relevant facts. In other words, informed and reasonable people may still disagree because the conflict is not settled by facts alone.", question_type: "conceptual", weight: 1.0 },
  { id: 146, order: 146, axis: "C11", key: 1, text: "Some moral conflicts involve unavoidable loss because no option fully honors every value. In other words, some choices require sacrificing a real value even when the best available decision is made.", question_type: "conceptual", weight: 1.0 },
  { id: 147, order: 147, axis: "C11", key: -1, text: "When constitutional rights conflict, courts should apply a stable hierarchy rather than balance the values differently in each case. In other words, courts would decide in advance that certain rights generally outrank others instead of weighing the competing rights differently in each case.", question_type: "applied", weight: 1.15, educational_content: "Assume that the conflicting rights have comparable constitutional status and no explicit constitutional text already settles the conflict." },
  { id: 148, order: 148, axis: "C11", key: -1, text: "Emergency medical triage should follow one transparent priority rule rather than combine several competing principles case by case. In other words, medical staff would follow one published rule, such as urgency or chance of survival, rather than combine several rules for each patient.", question_type: "applied", weight: 1.15, educational_content: "Assume that the emergency involves real scarcity and the chosen rule is published before clinicians know which individual patients will benefit." },
  { id: 149, order: 149, axis: "C11", key: -1, text: "Public institutions should adopt one consistent definition of human dignity across criminal, medical, and family law. In other words, the same basic meaning of human dignity would guide decisions in prisons, hospitals, and family law.", question_type: "applied", weight: 1.15 },
  { id: 150, order: 150, axis: "C11", key: -1, text: "When equal treatment conflicts with religious custom, equal treatment should have presumptive priority rather than be balanced anew in every case. In other words, equal treatment would normally come first, although an exceptional religious burden could still justify a narrow exception.", question_type: "applied", weight: 1.15, educational_content: "Assume that the equal-treatment rule applies generally, the religious burden is serious, and any exception would affect other people's access or rights." },
  { id: 151, order: 151, axis: "C11", key: 1, text: "Conscientious exemptions should sometimes be allowed when they protect a serious moral commitment without imposing substantial harm on others. In other words, a person or institution could receive an exception from a general rule when the moral commitment is serious and other people are not substantially harmed.", question_type: "applied", weight: 1.15, educational_content: "Assume that the commitment is sincere and serious, and the exemption does not impose substantial costs, exclusion, or loss of rights on others." },
  { id: 152, order: 152, axis: "C11", key: 1, text: "End-of-life law should offer more than one ethically defensible option rather than enforce a single view of dignity. In other words, multiple options can include continued treatment, refusal, palliative sedation, or other legally defined choices.", question_type: "applied", weight: 1.15 },
  { id: 153, order: 153, axis: "C11", key: 1, text: "Land-use decisions should openly balance housing, heritage, livelihoods, and ecology rather than treat one value as overriding in every case. In other words, multi-criteria balancing explicitly weighs several goals instead of maximizing only one.", question_type: "applied", weight: 1.15 },
  { id: 154, order: 154, axis: "C11", key: 1, text: "Courts should acknowledge that some rights conflicts involve genuine losses on both sides rather than pretend one value always fully defeats the other. In other words, a court would admit that protecting one right can genuinely injure another and would explain why the chosen limit is justified.", question_type: "applied", weight: 1.15, educational_content: "Assume that both rights are genuine, neither is absolute under the constitution, and the court must publicly justify any limit." },
  { id: 155, order: 155, axis: "F1", key: -1, text: "Durable reform usually comes from incremental changes that institutions can absorb. In other words, reforms are more likely to last when introduced step by step so institutions and people can adjust.", question_type: "conceptual", weight: 1.0 },
  { id: 156, order: 156, axis: "F1", key: -1, text: "Rapid transformation often creates unintended harms greater than the problems it addresses. In other words, changing a system too quickly can create problems worse than the original problem.", question_type: "conceptual", weight: 1.0 },
  { id: 157, order: 157, axis: "F1", key: -1, text: "Stability and continuity have value even when significant reform is needed. In other words, keeping systems stable and continuous has value even while they are being improved.", question_type: "conceptual", weight: 1.0 },
  { id: 158, order: 158, axis: "F1", key: 1, text: "Entrenched systems sometimes require rapid structural change rather than gradual adjustment. In other words, deeply rooted problems may require replacing major structures quickly instead of making small adjustments.", question_type: "conceptual", weight: 1.0 },
  { id: 159, order: 159, axis: "F1", key: 1, text: "Disruption can be legitimate when ordinary channels consistently protect injustice. In other words, disruptive action can be justified when normal political or legal processes repeatedly preserve injustice.", question_type: "conceptual", weight: 1.0 },
  { id: 160, order: 160, axis: "F1", key: 1, text: "Compromise can preserve a harmful system by relieving the pressure for deeper reform. In other words, accepting a partial deal can sometimes weaken the pressure needed to fix the larger problem.", question_type: "conceptual", weight: 1.0 },
  { id: 161, order: 161, axis: "F1", key: -1, text: "A national social program should be tested in several regions and revised before being implemented everywhere. In other words, a pilot tests a policy on a limited scale before wider adoption.", question_type: "applied", weight: 1.15, educational_content: "Assume that the pilot regions are reasonably representative and the results will be independently evaluated before national expansion." },
  { id: 162, order: 162, axis: "F1", key: -1, text: "A movement should accept a meaningful partial emissions law now rather than reject it while waiting for a complete climate package. In other words, the scenario assumes the partial law creates a real improvement but does not achieve the movement's full goal.", question_type: "applied", weight: 1.15, educational_content: "Assume that the partial law creates a meaningful near-term improvement but falls well short of the movement's full program." },
  { id: 163, order: 163, axis: "F1", key: -1, text: "Police reform should proceed through staged standards, training, and oversight unless evidence shows the institutions cannot be repaired. In other words, staged reform changes rules and oversight over time rather than abolishing and replacing the institution at once.", question_type: "applied", weight: 1.15 },
  { id: 164, order: 164, axis: "F1", key: -1, text: "Employees who uncover wrongdoing should normally use protected reporting channels before releasing confidential material publicly. In other words, protected channels may include inspectors general, regulators, unions, courts, or designated compliance offices.", question_type: "applied", weight: 1.15, educational_content: "Assume that the protected channels are independent enough to investigate the allegation and can protect the employee from retaliation." },
  { id: 165, order: 165, axis: "F1", key: 1, text: "A constitutional convention may be justified when ordinary amendment procedures repeatedly prevent reform of a political system that is failing basic democratic functions. In other words, a specially authorized body could propose broad constitutional changes after normal amendment rules repeatedly block repairs to a failing system.", question_type: "applied", weight: 1.15, educational_content: "Assume that ordinary amendment procedures have repeatedly failed despite broad support and the proposed convention is legally authorized." },
  { id: 166, order: 166, axis: "F1", key: 1, text: "A general strike can be legitimate when normal bargaining and elections cannot overcome entrenched labor abuses. In other words, a general strike is a broad work stoppage across multiple industries or sectors.", question_type: "applied", weight: 1.15, educational_content: "Assume that the labor abuses are severe, normal bargaining and elections have repeatedly failed, and the strike remains nonviolent." },
  { id: 167, order: 167, axis: "F1", key: 1, text: "A movement may reject a partial compromise when accepting it would remove the pressure needed for structural reform. In other words, the question assumes the partial measure provides some benefit but may reduce momentum for broader change.", question_type: "applied", weight: 1.15 },
  { id: 168, order: 168, axis: "F1", key: 1, text: "A deeply discredited agency may need to be abolished and rebuilt rather than improved through another round of internal reforms. In other words, abolition and rebuilding replace the organization, mandate, and operating rules rather than only changing leadership or procedures.", question_type: "applied", weight: 1.15, educational_content: "Assume that independent evidence shows persistent institutional failure that cannot be corrected merely by replacing current leaders." },
  { id: 169, order: 169, axis: "F2", key: -1, text: "Professional norms and oversight usually constrain misconduct within major institutions. In other words, professional rules, peer review, and oversight usually keep large institutions from serious misconduct.", question_type: "conceptual", weight: 1.0 },
  { id: 170, order: 170, axis: "F2", key: -1, text: "Institutions that expose errors and correct them deserve a presumption of good faith. In other words, an institution that openly admits and fixes mistakes should usually be trusted unless contrary evidence appears.", question_type: "conceptual", weight: 1.0 },
  { id: 171, order: 171, axis: "F2", key: -1, text: "Stable institutions generally produce more reliable decisions than improvised alternatives. In other words, established organizations with stable procedures usually make better decisions than temporary or improvised groups.", question_type: "conceptual", weight: 1.0 },
  { id: 172, order: 172, axis: "F2", key: 1, text: "Powerful institutions often protect their own interests while presenting their choices as neutral. In other words, institutions may present decisions as objective while quietly protecting their own power, reputation, or funding.", question_type: "conceptual", weight: 1.0 },
  { id: 173, order: 173, axis: "F2", key: 1, text: "Official expertise should be independently verifiable rather than accepted on authority. In other words, expert claims should be supported by evidence that outsiders can check, not accepted only because an authority says so.", question_type: "conceptual", weight: 1.0 },
  { id: 174, order: 174, axis: "F2", key: 1, text: "Transparency and external audit are more reliable than institutional assurances. In other words, independent review and open information provide more confidence than an institution simply asking to be trusted.", question_type: "conceptual", weight: 1.0 },
  { id: 175, order: 175, axis: "F2", key: -1, text: "A certified election result should be accepted after transparent procedures, bipartisan observation, and a completed independent audit. In other words, an election audit checks records or paper ballots using procedures independent of the original count.", question_type: "applied", weight: 1.15, educational_content: "Assume that the audit is genuinely independent, uses reliable records, and is completed before the result is treated as final." },
  { id: 176, order: 176, axis: "F2", key: -1, text: "When several independent research groups converge on the same finding, public policy should generally treat that consensus as reliable. In other words, independent studies reaching similar conclusions comes from separate teams, methods, or datasets reaching compatible conclusions.", question_type: "applied", weight: 1.15, educational_content: "Assume that the studies are methodologically sound, genuinely independent, and reach similar conclusions using different data or methods." },
  { id: 177, order: 177, axis: "F2", key: -1, text: "Judges should be presumed to be acting in good faith unless evidence shows corruption or undisclosed conflicts. In other words, a presumption of good faith can be rebutted by evidence and does not prevent appeals or oversight.", question_type: "applied", weight: 1.15 },
  { id: 178, order: 178, axis: "F2", key: -1, text: "A public-health agency may receive temporary operational discretion during an outbreak when it publishes its evidence and decisions for review. In other words, the agency could make day-to-day outbreak decisions within limits already set by law, without asking lawmakers to approve every action.", question_type: "applied", weight: 1.15, educational_content: "Assume that the discretion is temporary, limited by law, transparent, and subject to later legislative and judicial review." },
  { id: 179, order: 179, axis: "F2", key: 1, text: "Regulators should be required to publish models, assumptions, and uncertainty ranges before major rules take effect. In other words, models and uncertainty ranges show how projected effects depend on assumptions and incomplete evidence.", question_type: "applied", weight: 1.15, educational_content: "Assume that publication can protect legitimate personal privacy and security secrets while still allowing meaningful outside scrutiny." },
  { id: 180, order: 180, axis: "F2", key: 1, text: "Clinical-trial data supporting public recommendations should be available for independent reanalysis, not only summarized by sponsors or agencies. In other words, independent an independent check of the same data checks whether results depend on analytic choices, exclusions, or reporting.", question_type: "applied", weight: 1.15, educational_content: "Assume that qualified independent researchers can access sufficiently detailed data under privacy and security safeguards." },
  { id: 181, order: 181, axis: "F2", key: 1, text: "Senior officials should face strict cooling-off periods before taking paid roles in industries they regulated. In other words, a cooling-off period delays lobbying or employment connected to an official's former responsibilities.", question_type: "applied", weight: 1.15, educational_content: "Assume that the restriction applies only to industries directly connected to the official's recent regulatory authority." },
  { id: 182, order: 182, axis: "F2", key: 1, text: "Police and welfare algorithms should be subject to outside audits because agencies cannot be trusted to assess their own systems. In other words, an outside audit can evaluate accuracy, bias, security, documentation, and appeal procedures.", question_type: "applied", weight: 1.15, educational_content: "Assume that the outside auditor is institutionally independent and can examine data, design, outcomes, and appeal procedures." },
  { id: 183, order: 183, axis: "F3", key: -1, text: "Wrongdoers deserve punishment proportionate to the seriousness of their offense. In other words, the severity of punishment should match how serious the wrongdoing was.", question_type: "conceptual", weight: 1.0 },
  { id: 184, order: 184, axis: "F3", key: -1, text: "Public condemnation and punishment help reaffirm the moral boundaries of a community. In other words, punishment can publicly show which conduct a community considers unacceptable.", question_type: "conceptual", weight: 1.0 },
  { id: 185, order: 185, axis: "F3", key: -1, text: "Some offenses merit punishment even when it does not rehabilitate the offender. In other words, a person may deserve punishment even when punishment will not improve their future behavior.", question_type: "conceptual", weight: 1.0 },
  { id: 186, order: 186, axis: "F3", key: 1, text: "Justice should focus primarily on repairing harm and reintegrating people into society. In other words, justice should mainly repair the damage and help the offender return safely to the community.", question_type: "conceptual", weight: 1.0 },
  { id: 187, order: 187, axis: "F3", key: 1, text: "Victims and affected communities should have a meaningful role in resolving wrongdoing. In other words, people harmed by wrongdoing and their communities should help shape how the harm is addressed.", question_type: "conceptual", weight: 1.0 },
  { id: 188, order: 188, axis: "F3", key: 1, text: "Accountability can be achieved through restitution, treatment, and changed behavior rather than punishment alone. In other words, repayment, treatment, apology, supervision, and changed conduct can sometimes provide accountability without relying mainly on punishment.", question_type: "conceptual", weight: 1.0 },
  { id: 189, order: 189, axis: "F3", key: -1, text: "A professional who deliberately defrauds clients should lose their license even after full repayment and genuine remorse. In other words, professional discipline protects the public and can also express condemnation independent of criminal punishment.", question_type: "applied", weight: 1.15, educational_content: "Assume that the fraud was deliberate, serious, and directly related to the trust required by the profession." },
  { id: 190, order: 190, axis: "F3", key: -1, text: "A commander responsible for war crimes should face punishment even if prosecution complicates a peace agreement. In other words, peace agreements sometimes offer amnesty or reduced punishment in exchange for ending conflict.", question_type: "applied", weight: 1.15, educational_content: "Assume that credible evidence establishes responsibility and the prosecution is conducted by a fair court." },
  { id: 191, order: 191, axis: "F3", key: -1, text: "A repeat violent offender may deserve a long prison sentence even when rehabilitation appears unlikely. In other words, this scenario separates deserved punishment and confinement intended to prevent further harm from confidence in rehabilitation.", question_type: "applied", weight: 1.15, educational_content: "Assume that the prior violence is serious and repeated, and the sentence remains subject to lawful review." },
  { id: 192, order: 192, axis: "F3", key: -1, text: "A public official who knowingly sells decisions for bribes should serve prison time rather than receive only restitution and a ban from office. In other words, restitution returns illicit gains; a ban from office prevents future public service.", question_type: "applied", weight: 1.15 },
  { id: 193, order: 193, axis: "F3", key: 1, text: "A juvenile who commits a serious assault should be offered intensive treatment, restitution, and supervised reintegration rather than automatically being sentenced as an adult. In other words, a restorative sentence can include confinement or supervision while emphasizing treatment, repair, and reintegration.", question_type: "applied", weight: 1.15, educational_content: "Assume that the treatment and supervision plan can protect the public and is not automatic release without accountability." },
  { id: 194, order: 194, axis: "F3", key: 1, text: "A company that causes major pollution should be required to repair the damage, compensate communities, and submit to monitoring rather than rely mainly on punitive fines. In other words, remediation repairs environmental damage; monitoring verifies future compliance.", question_type: "applied", weight: 1.15 },
  { id: 195, order: 195, axis: "F3", key: 1, text: "A school response to serious student violence should include victim participation, treatment, and a safety plan rather than rely only on exclusion. In other words, victim participation must be voluntary and can occur without face-to-face contact.", question_type: "applied", weight: 1.15 },
  { id: 196, order: 196, axis: "F3", key: 1, text: "A truth commission may offer reduced punishment for full disclosure and victim reparations after a civil conflict. In other words, truth commissions investigate patterns of abuse and may trade reduced punishment for disclosure, acknowledgment, and reparations.", question_type: "applied", weight: 1.15, educational_content: "Assume that full disclosure is verified, victims receive meaningful reparations, and the reduced punishment remains proportionate to the agreement." },
  { id: 197, order: 197, axis: "F4", key: -1, text: "Elected majorities should normally prevail over judges and unelected constitutional bodies. In other words, elected lawmakers and voters should usually have the final say rather than judges or other unelected bodies.", question_type: "conceptual", weight: 1.0 },
  { id: 198, order: 198, axis: "F4", key: -1, text: "A sustained democratic majority should be able to change most fundamental rules. In other words, a clear majority that continues over time should be able to change most constitutional or basic political rules.", question_type: "conceptual", weight: 1.0 },
  { id: 199, order: 199, axis: "F4", key: -1, text: "Minority protections should not become a general excuse for overriding ordinary democratic decisions. In other words, claims about protecting minorities should not routinely allow courts or unelected bodies to block normal majority decisions.", question_type: "conceptual", weight: 1.0 },
  { id: 200, order: 200, axis: "F4", key: 1, text: "Majority rule must be limited by rights that majorities cannot easily remove. In other words, some basic rights should remain protected even when most voters want to remove them.", question_type: "conceptual", weight: 1.0 },
  { id: 201, order: 201, axis: "F4", key: 1, text: "Courts may legitimately invalidate laws that violate constitutional protections. In other words, courts may properly stop a democratically passed law when it violates rights protected by the constitution.", question_type: "conceptual", weight: 1.0 },
  { id: 202, order: 202, axis: "F4", key: 1, text: "Fundamental political rules should require broader agreement than a temporary majority. In other words, changing the basic rules of government should require more lasting and widespread support than winning one ordinary election.", question_type: "conceptual", weight: 1.0 },
  { id: 203, order: 203, axis: "F4", key: -1, text: "Elected legislatures, not courts, should normally have the final word on contested social policy. In other words, on disputed social policy, courts would generally leave the final decision to elected lawmakers unless the constitution clearly requires otherwise.", question_type: "applied", weight: 1.15, educational_content: "Assume that the dispute concerns policy judgment rather than a clear violation of explicit constitutional text." },
  { id: 204, order: 204, axis: "F4", key: -1, text: "A constitution should be amendable through two successive national majority votes without requiring a supermajority. In other words, a supermajority requires more than half, such as two-thirds, to approve a change.", question_type: "applied", weight: 1.15, educational_content: "Assume that the two majority votes occur at separate elections, allowing time for public reconsideration." },
  { id: 205, order: 205, axis: "F4", key: -1, text: "A national referendum should be able to reverse a policy created by judicial interpretation when voters clearly reject it. In other words, voters could use a formally authorized national vote to reverse a rule that arose from a court's interpretation.", question_type: "applied", weight: 1.15, educational_content: "Assume that the constitution expressly permits the referendum override and basic individual rights remain protected." },
  { id: 206, order: 206, axis: "F4", key: -1, text: "Election rules may be changed by an elected majority after public debate rather than being insulated from ordinary politics. In other words, election law would remain changeable through the ordinary democratic process rather than requiring a commission, supermajority, or constitutional amendment.", question_type: "applied", weight: 1.15, educational_content: "Assume that the proposed change is public before the vote and applies prospectively rather than altering rules to decide an election already underway." },
  { id: 207, order: 207, axis: "F4", key: 1, text: "Courts should invalidate a popular law that denies equal civil rights to a religious or ethnic minority. In other words, constitutional invalidation prevents enforcement even when the law was democratically enacted.", question_type: "applied", weight: 1.15, educational_content: "Assume that the law clearly denies an equal civil right rather than merely creating an incidental or disputed burden." },
  { id: 208, order: 208, axis: "F4", key: 1, text: "Suspending core civil liberties during an emergency should require a legislative supermajority and prompt judicial review. In other words, prompt review requires courts to assess legality during, not only after, the emergency.", question_type: "applied", weight: 1.15, educational_content: "Assume that the emergency is genuine and the review occurs while the restriction is still operating." },
  { id: 209, order: 209, axis: "F4", key: 1, text: "Independent election-administration rules should be protected from unilateral change by the party currently in power. In other words, the governing party could not change election-administration rules by itself through an ordinary majority vote.", question_type: "applied", weight: 1.15, educational_content: "Assume that the protection applies symmetrically regardless of which party is in power." },
  { id: 210, order: 210, axis: "F4", key: 1, text: "Fundamental constitutional amendments should require broader and more durable agreement than a single election majority. In other words, broader agreement may require supermajorities, regional consent, or approval across multiple elections.", question_type: "applied", weight: 1.15, educational_content: "Assume that the amendment concerns the basic structure of government rather than an ordinary policy detail." },
  { id: 211, order: 211, axis: "F5", key: -1, text: "Experts should advise democratic leaders but should not make value-laden public decisions for them. In other words, experts should explain evidence and options, but elected leaders should make decisions involving moral goals or political tradeoffs.", question_type: "conceptual", weight: 1.0 },
  { id: 212, order: 212, axis: "F5", key: -1, text: "Democratic accountability is more important than technically optimal policy. In other words, it is more important that decision-makers answer to voters than that specialists choose the policy they consider most effective.", question_type: "conceptual", weight: 1.0 },
  { id: 213, order: 213, axis: "F5", key: -1, text: "Elected officials should retain authority even when professional bodies strongly disagree. In other words, elected officials should make the final decision even when expert organizations strongly oppose it.", question_type: "conceptual", weight: 1.0 },
  { id: 214, order: 214, axis: "F5", key: 1, text: "Technical decisions should often be delegated to qualified professionals insulated from day-to-day politics. In other words, trained specialists should often make technical decisions without direct political control over each choice.", question_type: "conceptual", weight: 1.0 },
  { id: 215, order: 215, axis: "F5", key: 1, text: "Expertise can justify limiting the discretion of elected officials in specialized fields. In other words, in highly specialized areas, expert bodies may be allowed to restrict or overrule some choices by elected officials.", question_type: "conceptual", weight: 1.0 },
  { id: 216, order: 216, axis: "F5", key: 1, text: "Evidence-based standards should constrain popular preferences when the public cannot easily evaluate complex risks. In other words, technical safety rules may properly limit what most voters want when the risks are too complex for ordinary public judgment.", question_type: "conceptual", weight: 1.0 },
  { id: 217, order: 217, axis: "F5", key: -1, text: "Elected lawmakers should decide whether government may use AI surveillance rather than delegate the value judgment to a technical commission. In other words, a technical commission can assess feasibility and risk, but the question concerns who makes the final moral or political choice.", question_type: "applied", weight: 1.15, educational_content: "Assume that experts still assess technical feasibility and risk; the question is who makes the final moral and political choice." },
  { id: 218, order: 218, axis: "F5", key: -1, text: "Local voters should make the final land-use tradeoff after experts present the evidence. In other words, experts provide analysis, while voters retain final authority over the tradeoff.", question_type: "applied", weight: 1.15, educational_content: "Assume that experts present credible evidence and practical options before the vote." },
  { id: 219, order: 219, axis: "F5", key: -1, text: "Civilian elected leaders should determine military objectives rather than defer to commanders because the issue is technically complex. In other words, civilian control gives elected authorities final responsibility for political objectives and acceptable risk.", question_type: "applied", weight: 1.15, educational_content: "Assume that civilian leaders have access to the relevant military advice and intelligence." },
  { id: 220, order: 220, axis: "F5", key: -1, text: "Elected school boards should set curriculum priorities rather than delegate them entirely to academic specialists. In other words, curriculum priorities combine technical pedagogy with public judgments about goals and content.", question_type: "applied", weight: 1.15, educational_content: "Assume that academic specialists advise the board and professional teaching standards remain enforceable." },
  { id: 221, order: 221, axis: "F5", key: 1, text: "An independent central bank should set short-term interest rates without needing approval from elected officials. In other words, appointed monetary officials would raise or lower short-term interest rates within a legal mandate without seeking approval from elected leaders.", question_type: "applied", weight: 1.15, educational_content: "Assume that the bank operates under a clear legal mandate, publishes its reasoning, and remains accountable for meeting stated goals." },
  { id: 222, order: 222, axis: "F5", key: 1, text: "A scientific public-health body should set vaccine schedules using published evidence rather than popular vote. In other words, vaccine schedules determine recommended timing and eligibility based on disease risk and evidence.", question_type: "applied", weight: 1.15, educational_content: "Assume that the scientific body publishes its evidence, conflicts, and reasoning and its schedule can be reviewed as evidence changes." },
  { id: 223, order: 223, axis: "F5", key: 1, text: "An independent grid operator should be able to order reliability investments that elected officials may find politically unpopular. In other words, a grid operator coordinates electricity supply and transmission to prevent instability and outages.", question_type: "applied", weight: 1.15, educational_content: "Assume that the operator is independent of market participants, uses published reliability standards, and must justify the investment." },
  { id: 224, order: 224, axis: "F5", key: 1, text: "Exposure limits for toxic chemicals should be set by technical panels using transparent risk methods. In other words, specialists would set the maximum amount of a toxic substance people may safely encounter, using public evidence and stated safety margins.", question_type: "applied", weight: 1.15, educational_content: "Assume that the panel publishes the evidence, assumptions, safety margins, conflicts of interest, and a process for later revision." },
  { id: 225, order: 225, axis: "F6", key: -1, text: "Citizens should decide major public questions directly whenever practical. In other words, voters should make major decisions themselves instead of always acting through representatives.", question_type: "conceptual", weight: 1.0 },
  { id: 226, order: 226, axis: "F6", key: -1, text: "Referendums and initiatives are necessary checks on a self-protecting political class. In other words, direct votes and citizen-proposed laws help prevent elected officials from protecting their own power.", question_type: "conceptual", weight: 1.0 },
  { id: 227, order: 227, axis: "F6", key: -1, text: "Voters should be able to recall officials who lose public confidence before the next scheduled election. In other words, voters should be able to remove an official before the next election if enough public support for removal exists.", question_type: "conceptual", weight: 1.0 },
  { id: 228, order: 228, axis: "F6", key: 1, text: "Representatives can weigh evidence and negotiate tradeoffs better than mass referendums. In other words, representatives can study evidence, revise proposals, and make compromises more effectively than a single yes-or-no public vote.", question_type: "conceptual", weight: 1.0 },
  { id: 229, order: 229, axis: "F6", key: 1, text: "Complex policies should be shaped through deliberation and amendment rather than a single popular vote. In other words, complicated laws should be developed through debate and revision rather than accepted or rejected as one fixed proposal.", question_type: "conceptual", weight: 1.0 },
  { id: 230, order: 230, axis: "F6", key: 1, text: "Elected representatives should have discretion to make decisions that differ from current polling. In other words, representatives should sometimes use their own judgment instead of following the latest opinion poll.", question_type: "conceptual", weight: 1.0 },
  { id: 231, order: 231, axis: "F6", key: -1, text: "Voters should be able to legalize or prohibit major policies through ballot initiatives even when the legislature disagrees. In other words, a ballot initiative lets voters enact or repeal law directly after a petition process.", question_type: "applied", weight: 1.15, educational_content: "Assume that the initiative follows a valid petition and voting process and does not remove protected constitutional rights." },
  { id: 232, order: 232, axis: "F6", key: -1, text: "A mayor should be subject to recall before the next election when a petition reaches a high signature threshold. In other words, a recall election asks voters whether to remove an official before the scheduled end of the term.", question_type: "applied", weight: 1.15, educational_content: "Assume that the signature threshold is high enough to show broad concern and the official receives a fair public vote." },
  { id: 233, order: 233, axis: "F6", key: -1, text: "Major long-term public borrowing should require approval in a referendum. In other words, public borrowing commits future revenue to repay principal and interest.", question_type: "applied", weight: 1.15, educational_content: "Assume that the requirement applies only above a clearly defined long-term borrowing threshold." },
  { id: 234, order: 234, axis: "F6", key: -1, text: "Residents should directly vote on a meaningful share of the municipal budget. In other words, participatory budgeting lets residents propose and vote on specified public expenditures.", question_type: "applied", weight: 1.15, educational_content: "Assume that the share is large enough to affect priorities but leaves legally required services and debt payments outside the vote." },
  { id: 235, order: 235, axis: "F6", key: 1, text: "Complex tax reform should be decided by elected representatives after hearings and amendment rather than by a single up-or-down referendum. In other words, hearings and amendment allow provisions to be revised separately before final passage.", question_type: "applied", weight: 1.15, educational_content: "Assume that the reform is technically interconnected and lawmakers publish the proposed changes before voting." },
  { id: 236, order: 236, axis: "F6", key: 1, text: "Legislatures should be allowed to make unpopular compromises that would be difficult to assemble through separate ballot questions. In other words, a legislative package can link concessions across issues that voters would otherwise consider separately.", question_type: "applied", weight: 1.15, educational_content: "Assume that the compromise package is transparent and each linked concession is disclosed to voters." },
  { id: 237, order: 237, axis: "F6", key: 1, text: "Citizens' views should inform policy, but representatives should retain discretion to change position after reviewing evidence. In other words, representatives would listen to voters but could change their position after studying evidence and would be expected to explain why.", question_type: "applied", weight: 1.15, educational_content: "Assume that representatives must explain their reasoning publicly and remain accountable at the next election." },
  { id: 238, order: 238, axis: "F6", key: 1, text: "Minority-rights protections should not be submitted to frequent popular referendums. In other words, frequent referendums can repeatedly reopen settled legal status and expose small groups to majority campaigns.", question_type: "applied", weight: 1.15, educational_content: "Assume that the protections concern basic legal status and remain open to ordinary legislative and judicial review when circumstances materially change." },
  { id: 239, order: 239, axis: "F7", key: -1, text: "Military force usually creates new dangers that outlast the problem it was meant to solve. In other words, war often creates lasting instability, retaliation, or suffering beyond the original dispute.", question_type: "conceptual", weight: 1.0 },
  { id: 240, order: 240, axis: "F7", key: -1, text: "Diplomacy and economic engagement should be preferred even when they take longer. In other words, negotiation, trade, and other peaceful tools should be used even when they work slowly.", question_type: "conceptual", weight: 1.0 },
  { id: 241, order: 241, axis: "F7", key: -1, text: "The risk to civilians should create a strong presumption against using force. In other words, the chance of civilian deaths should make governments strongly reluctant to use military force.", question_type: "conceptual", weight: 1.0 },
  { id: 242, order: 242, axis: "F7", key: 1, text: "Peace often depends on a credible willingness to use military force. In other words, other countries may avoid aggression only when they believe military retaliation is possible.", question_type: "conceptual", weight: 1.0 },
  { id: 243, order: 243, axis: "F7", key: 1, text: "Military intervention can be justified to prevent a substantially worse outcome. In other words, using force can be right when it prevents a much greater harm that cannot otherwise be stopped.", question_type: "conceptual", weight: 1.0 },
  { id: 244, order: 244, axis: "F7", key: 1, text: "Alliances are meaningful only when members are willing to fight for one another. In other words, a defense alliance has little value unless members are prepared to use force when another member is attacked.", question_type: "conceptual", weight: 1.0 },
  { id: 245, order: 245, axis: "F7", key: -1, text: "A country should not launch a preventive war based only on suspicion that another state may develop dangerous weapons. In other words, a preventive war attacks a possible future danger before the other country has begun or is about to begin an attack.", question_type: "applied", weight: 1.15, educational_content: "Assume that the suspected threat is not imminent and reliable peaceful monitoring remains available." },
  { id: 246, order: 246, axis: "F7", key: -1, text: "Diplomacy, inspections, and targeted sanctions should be exhausted before conventional military force is used. In other words, targeted sanctions focus on leaders, firms, or sectors rather than broadly restricting an entire population.", question_type: "applied", weight: 1.15, educational_content: "Assume that the listed peaceful measures are feasible, targeted, and given a reasonable chance to work." },
  { id: 247, order: 247, axis: "F7", key: -1, text: "Arms sales should end when an allied government repeatedly uses the weapons against civilians. In other words, arms transfers can include sales, grants, maintenance, ammunition, and technical support.", question_type: "applied", weight: 1.15, educational_content: "Assume that the civilian harm is repeated, credibly documented, and caused with weapons or support supplied by the country." },
  { id: 248, order: 248, axis: "F7", key: -1, text: "Military conscription should be reserved for defense against a direct and severe threat to the country. In other words, conscription requires eligible people to perform military service.", question_type: "applied", weight: 1.15, educational_content: "Assume that the service requirement is limited to the duration and scale of the direct severe threat." },
  { id: 249, order: 249, axis: "F7", key: 1, text: "A treaty ally that is invaded should be defended militarily even when doing so creates serious costs and escalation risks. In other words, collective-defense treaties commit members to assist one another after an attack.", question_type: "applied", weight: 1.15, educational_content: "Assume that the treaty obligation is clear, the ally did not provoke the invasion, and defensive aims remain limited." },
  { id: 250, order: 250, axis: "F7", key: 1, text: "Limited military strikes can be justified to stop an imminent mass killing when no effective peaceful option remains. In other words, a limited strike uses force for a narrow objective rather than broader regime change or occupation.", question_type: "applied", weight: 1.15, educational_content: "Assume that the mass killing is imminent, attribution is reliable, and no effective peaceful option can act in time." },
  { id: 251, order: 251, axis: "F7", key: 1, text: "A credible nuclear deterrent should be maintained as long as rival states possess nuclear weapons. In other words, the country would keep nuclear weapons capable of surviving an attack and striking back so rivals expect aggression to be met with devastating retaliation.", question_type: "applied", weight: 1.15, educational_content: "Assume that rival nuclear forces remain capable of attacking and the deterrent is maintained under strict command, safety, and civilian-control rules." },
  { id: 252, order: 252, axis: "F7", key: 1, text: "A major state-sponsored cyberattack on critical infrastructure may justify proportionate offensive retaliation. In other words, after reliable attribution, the country could use a limited cyber, economic, or military response matched to the scale of the attack.", question_type: "applied", weight: 1.15, educational_content: "Assume that attribution is based on high-confidence evidence and the response is limited to what is necessary to deter or stop comparable attacks." },
  { id: 253, order: 253, axis: "C1", key: 1, text: "Private firms should be allowed to use biometric screening with customer consent, even if it substantially reduces privacy. In other words, biometric screening uses traits such as face, fingerprint, or voice to verify identity.", question_type: "applied", weight: 1.25, educational_content: "Assume that consent is informed, refusal remains practical, and the company does not use the biometric data for unrelated purposes." },
  { id: 254, order: 254, axis: "C1", key: -1, text: "Government should require private venues to install standardized surveillance systems as a condition of operating, even if the mandate raises costs and reduces privacy. In other words, a surveillance mandate can require cameras, identity checks, data retention, or reporting as a condition of operating.", question_type: "applied", weight: 1.25, educational_content: "Assume that the mandate is publicly defined, applies consistently, and includes enforceable limits on data access and retention." },
  { id: 255, order: 255, axis: "C4", key: 1, text: "Cities should be free to cap fees charged by delivery platforms, even if some firms leave those markets. In other words, platform fee caps limit the commission charged to restaurants, drivers, or customers.", question_type: "applied", weight: 1.25, educational_content: "Assume that the city has legal authority over the fees and the cap is publicly stated before firms decide whether to remain." },
  { id: 256, order: 256, axis: "C4", key: -1, text: "The national government should require public ownership of water utilities in every region even when local voters prefer private provision. In other words, a national mandate would remove local choice over whether the utility is publicly or privately owned.", question_type: "applied", weight: 1.25, educational_content: "Assume that the national law provides compensation for lawful private assets and preserves ordinary service and rate protections." },
  { id: 257, order: 257, axis: "C1", key: 1, text: "Countries should accept binding international competition rules that prohibit subsidies and favoritism toward domestic firms. In other words, the international rules would stop governments from giving domestic firms special subsidies, contracts, or legal advantages that distort competition.", question_type: "applied", weight: 1.25, educational_content: "Assume that the rules apply symmetrically, distinguish legitimate safety rules from favoritism, and use an independent dispute process." },
  { id: 258, order: 258, axis: "C1", key: -1, text: "A group of countries should coordinate public subsidies for strategic industries through a binding international agreement. In other words, the agreement would pool or coordinate state support rather than prohibit industrial policy.", question_type: "applied", weight: 1.25, educational_content: "Assume that participating countries voluntarily accept the binding agreement and disclose the subsidies they coordinate." },
  { id: 259, order: 259, axis: "C6", key: 1, text: "Charitable donors should be free to direct their money to the neediest people worldwide without tax rules favoring domestic beneficiaries. In other words, tax neutrality means the government does not favor domestic over foreign beneficiaries when recognizing charitable gifts.", question_type: "applied", weight: 1.25, educational_content: "Assume that the issue is only whether tax law favors domestic beneficiaries, not whether government must subsidize the donation." },
  { id: 260, order: 260, axis: "C2", key: 1, text: "Charitable donors should be free to restrict privately funded scholarships to members of their own community even when equally needy outsiders apply. In other words, a donor-directed restriction uses private funds but limits eligibility according to community membership.", question_type: "applied", weight: 1.25, educational_content: "Assume that the scholarship uses private funds and the donor's restriction does not violate an independently applicable law." },
  { id: 261, order: 261, axis: "C2", key: -1, text: "Religious schools receiving public funds should follow the same nondiscrimination rules as other publicly funded schools, even when those rules conflict with doctrine. In other words, a religious school could choose whether to accept public money, but accepting it would require following the same equal-treatment rules as other publicly funded schools.", question_type: "applied", weight: 1.25, educational_content: "Assume that accepting public funds is voluntary and the nondiscrimination rules are clear before the school accepts them." },
  { id: 262, order: 262, axis: "C5", key: -1, text: "Government should provide a family allowance only to married couples raising children in a traditional household. In other words, a family allowance is a public cash benefit tied to children or household status.", question_type: "applied", weight: 1.25, educational_content: "Assume that the benefit is genuinely unavailable to unmarried or nontraditional households with otherwise similar children and needs." },
  { id: 263, order: 263, axis: "C9", key: 1, text: "Government may prohibit private development in a critical wildlife corridor even when owners are willing to accept environmental mitigation. In other words, a wildlife corridor connects habitats needed for migration, breeding, and genetic diversity.", question_type: "applied", weight: 1.25, educational_content: "Assume that the corridor is critical to species survival and proposed mitigation cannot preserve its connecting function." },
  { id: 264, order: 264, axis: "C3", key: -1, text: "During a severe food shortage, government may require landowners to clear protected habitat for emergency crop production. In other words, the scenario uses compulsory production to increase food supply at direct ecological cost.", question_type: "applied", weight: 1.25, educational_content: "Assume that the shortage threatens widespread severe hunger and less damaging ways to increase food supply cannot act in time." },
  { id: 265, order: 265, axis: "C7", key: 1, text: "A state or province should be allowed to join an international climate compact even when the national government objects. In other words, a subnational government could enter a formal cross-border climate agreement even though the national government opposes it.", question_type: "applied", weight: 1.25, educational_content: "Assume that the constitution permits subnational governments to join this kind of compact and the agreement does not bind the national government beyond that region." },
  { id: 266, order: 266, axis: "C7", key: -1, text: "Regions should be free to reject an international agreement adopted by the national government when the agreement intrudes on local authority. In other words, a region could decline to carry out a national government's international commitment when that commitment overrides powers normally reserved to the region.", question_type: "applied", weight: 1.25, educational_content: "Assume that the constitution permits a regional opt-out and the agreement mainly governs matters normally controlled by the region." },
  { id: 267, order: 267, axis: "C5", key: 1, text: "Fertility clinics should be allowed to offer new reproductive technologies once safety is established, even when the technologies challenge traditional ideas about family. In other words, reproductive technologies can change biological, gestational, and social relationships within families.", question_type: "applied", weight: 1.25, educational_content: "Assume that independent evidence establishes safety and participants receive clear information and voluntary choice." },
  { id: 268, order: 268, axis: "C8", key: -1, text: "Government should restrict automated systems that reproduce traditional gender and family assumptions, even if doing so slows deployment of useful AI. In other words, government would slow or limit an automated system when testing shows that it carries traditional assumptions about gender or family into important decisions.", question_type: "applied", weight: 1.25, educational_content: "Assume that the biased assumptions are documented, the restriction is targeted to the affected uses, and less restrictive corrections are insufficient." },
  { id: 269, order: 269, axis: "C7", key: 1, text: "A regional union should allocate asylum seekers among member states by capacity and need, even when voters in one state want to prioritize co-nationals. In other words, the union would use one transparent formula to place asylum seekers according to capacity and vulnerability rather than national preference.", question_type: "applied", weight: 1.25, educational_content: "Assume that the formula, funding, and capacity measures are public and applicants retain ordinary legal protections." },
  { id: 270, order: 270, axis: "C6", key: -1, text: "As one policy package, a country should join a regional trade-and-migration union while reserving selected welfare benefits for its own citizens. In other words, the country would accept shared trade and migration rules while keeping specified public benefits available only to its own citizens.", question_type: "applied", weight: 1.25, educational_content: "Assume that the union legally permits the welfare reservation and the package is considered as a whole rather than as three separate questions." },
  { id: 271, order: 271, axis: "C9", key: -1, text: "Large desalination plants should be built to secure water for cities even when they cause manageable but significant harm to marine ecosystems. In other words, desalination removes salt from water and can affect marine life through intake systems, energy use, and concentrated brine discharge.", question_type: "applied", weight: 1.25, educational_content: "Assume that the water need is serious, the ecological damage is significant but technically manageable, and lower-impact alternatives are insufficient." },
  { id: 272, order: 272, axis: "C9", key: 1, text: "Precision fermentation and cultivated meat should be deployed to reduce land use and animal suffering even if they disrupt conventional agriculture. In other words, new food technologies would replace some conventional livestock farming, reducing land use and animal suffering while disrupting existing farmers and industries.", question_type: "applied", weight: 1.25, educational_content: "Assume that the products meet ordinary food-safety standards and the disruption to existing agriculture is expected to be substantial." },
  { id: 273, order: 273, axis: "C8", key: -1, text: "Heritable gene editing should remain prohibited because altering future persons crosses a moral boundary even if it could prevent serious disease. In other words, heritable changes can affect descendants who cannot consent to the intervention.", question_type: "applied", weight: 1.25, educational_content: "Assume that the intervention could prevent serious disease but would create changes inherited by people who cannot consent." },
  { id: 274, order: 274, axis: "C10", key: 1, text: "Because societies hold different moral views about human enhancement, deployment should be paused until broad cross-cultural consent exists. In other words, deployment would wait for broad agreement across different cultures because the technology changes human abilities in morally disputed ways.", question_type: "applied", weight: 1.25, educational_content: "Assume that broad cross-cultural consent means strong agreement across diverse societies, not unanimity by every person or government." },
  { id: 275, order: 275, axis: "C11", key: 1, text: "Environmental law should balance species protection, housing, livelihoods, and cultural use case by case rather than give any one value automatic priority. In other words, officials would weigh several genuine interests in each case while still enforcing minimum protections for species and ecosystems.", question_type: "applied", weight: 1.25, educational_content: "Assume that minimum legal protections remain in force and the case-by-case process must publicly explain how each value was weighed." },
  { id: 276, order: 276, axis: "C9", key: -1, text: "Environmental law should permit essential human development to override habitat protection when several legitimate values conflict and no single value has absolute priority. In other words, the scenario treats ecological protection as one important value among several rather than an absolute side constraint.", question_type: "applied", weight: 1.25, educational_content: "Assume that the development is essential, lower-harm alternatives are unavailable, and habitat protection remains an important consideration rather than being ignored." },
  { id: 277, order: 277, axis: "C3", key: 1, text: "A movement may nonviolently occupy a government building to force urgent reform when lawful channels have repeatedly failed. In other words, an occupation remains nonviolent but interferes with normal use of a public building.", question_type: "applied", weight: 1.25, educational_content: "Assume that the occupation is nonviolent, lawful channels have repeatedly failed, and emergency services and personal safety are not obstructed." },
  { id: 278, order: 278, axis: "F5", key: 1, text: "An expert regulatory agency should receive broad discretion only as part of a package requiring public data, public models, conflict disclosures, and independent audits. In other words, the agency would receive freedom to choose methods and timing only if outsiders can inspect the evidence, models, financial interests, and audit results.", question_type: "applied", weight: 1.25, educational_content: "Assume that the transparency and audit safeguards are treated as one mandatory package and remain enforceable throughout the delegation." },
  { id: 279, order: 279, axis: "F4", key: 1, text: "A constitutional court may replace a voter-approved mandatory prison sentence with a restorative sentence when proportionality review finds the punishment excessive for the offense. In other words, the court would find the mandatory punishment excessively harsh for the offense and substitute a sentence focused more on repair and rehabilitation.", question_type: "applied", weight: 1.25, educational_content: "Assume that the court has lawful authority to conduct proportionality review and the finding of excessiveness is based on the offense and the person's circumstances." },
  { id: 280, order: 280, axis: "F6", key: -1, text: "A citywide referendum should be able to overturn a neighborhood board's zoning decision. In other words, the citywide electorate is a higher territorial level than the neighborhood board.", question_type: "applied", weight: 1.25, educational_content: "Assume that the referendum is legally authorized, includes the whole municipality, and the neighborhood board's decision is not protected by a higher constitutional right." },
  { id: 281, order: 281, axis: "F7", key: 1, text: "A country should join a mutual-defense alliance that obligates it to fight if any member is attacked. In other words, a mutual-defense clause creates a standing obligation rather than a case-by-case promise.", question_type: "applied", weight: 1.25, educational_content: "Assume that the mutual-defense obligation is explicit, limited to an actual armed attack, and each member retains civilian control of its forces." },
  { id: 282, order: 282, axis: "F6", key: 1, text: "Legislators should negotiate and enact one limited reform at a time rather than put one sweeping package to a direct public vote. In other words, elected representatives would pass smaller negotiated changes instead of asking voters to accept or reject one large package without amendment.", question_type: "applied", weight: 1.25, educational_content: "Assume that the limited reform and sweeping package address the same policy problem and the smaller reform is capable of producing a real benefit." },
  { id: 283, order: 283, axis: "F1", key: 1, text: "A newly elected reform government should temporarily freeze the assets of officials credibly implicated in corruption while it rapidly restructures compromised agencies, before final judgments are complete. In other words, the government could freeze suspected corrupt officials' assets before final judgments while rapidly rebuilding compromised agencies, subject to prompt court supervision.", question_type: "applied", weight: 1.25, educational_content: "Assume that credible evidence supports the corruption allegations, a court reviews each freeze promptly, and the restraints automatically expire unless renewed." },
  { id: 284, order: 284, axis: "F6", key: -1, text: "Residents of a municipality should decide a major local land-use plan by binding referendum rather than leave the decision to the national legislature. In other words, a binding referendum gives voters direct decision authority rather than an advisory role.", question_type: "applied", weight: 1.25, educational_content: "Assume that the municipality has legal authority over the plan and the referendum is binding under existing law." },
  { id: 285, order: 285, axis: "C7", key: -1, text: "A country should launch a limited unilateral strike against an imminent external threat even when international institutions refuse authorization. In other words, unilateral force is undertaken without authorization from a treaty body, regional organization, or the United Nations.", question_type: "applied", weight: 1.25, educational_content: "Assume that the threat is imminent and serious, peaceful alternatives cannot act in time, and international institutions have expressly refused authorization." },
  { id: 286, order: 286, axis: "F6", key: 1, text: "A newly elected legislature should enact one comprehensive constitutional package quickly rather than divide the changes among separate referendums or smaller bills. In other words, representatives would pass several connected constitutional changes together during one reform period instead of sending each change to voters or passing it separately.", question_type: "applied", weight: 1.25, educational_content: "Assume that the legislature has legal authority to enact the package and the connected changes are publicly available before the vote." },
  { id: 287, order: 287, axis: "F2", key: -1, text: "An independent central bank should be allowed to set interest rates without elected interference because its professional safeguards are generally trustworthy. In other words, appointed monetary officials would set interest rates without political interference because transparent rules, professional standards, and oversight are assumed to work.", question_type: "applied", weight: 1.25, educational_content: "Assume that the professional safeguards include transparency, conflict rules, independent review, and a clear legal mandate." },
  { id: 288, order: 288, axis: "F3", key: -1, text: "A constitutional court should strike down a voter-approved amnesty for officials who committed torture because some offenses require proportionate punishment. In other words, the court would cancel an amnesty approved by voters because torture is treated as an offense for which some punishment is always required.", question_type: "applied", weight: 1.25, educational_content: "Assume that the torture findings are established through a fair process and the amnesty would otherwise remove all criminal liability." },
  { id: 289, order: 289, axis: "C10", key: -1, text: "A hospital ethics board should give protection of innocent life lexical priority over autonomy, dignity, and social cost whenever those values conflict. In other words, lexical priority means that protecting innocent life would always come first instead of being weighed against autonomy, dignity, or cost case by case.", question_type: "applied", weight: 1.25, educational_content: "Assume that the values genuinely conflict in the case and the rule would apply categorically rather than only create a rebuttable presumption." },
  { id: 290, order: 290, axis: "C11", key: -1, text: "A society may ground public ethics in one coherent moral tradition even if that tradition is historically contingent rather than objectively true. In other words, a society could consistently rank public values using one inherited tradition even while admitting that history created the tradition and that it is not objectively true.", question_type: "applied", weight: 1.25, educational_content: "Assume that the tradition can be publicly criticized and changed through lawful processes even though it supplies one coherent ranking of values." },
  { id: 291, order: 291, axis: "F2", key: 1, text: "When watchdog evidence shows that an agency has repeatedly concealed corruption, its structure should be replaced quickly rather than repaired through gradual internal reforms. In other words, structural replacement changes authority, staffing, and procedures rather than relying only on internal corrective measures.", question_type: "applied", weight: 1.25, educational_content: "Assume that the concealment and corruption are established by credible independent evidence, not merely alleged." },
  { id: 292, order: 292, axis: "F1", key: -1, text: "Even when major institutions are untrustworthy, reform should proceed through audited incremental changes rather than wholesale replacement. In other words, audited incremental reform changes bounded components while measuring results before broader restructuring.", question_type: "applied", weight: 1.25, educational_content: "Assume that each incremental change is independently audited, measurable, and reversible if it fails." },
  { id: 293, order: 293, axis: "C3", key: -1, text: "Repeat violent offenders should receive long incapacitating sentences when confinement is necessary to protect the public, even if rehabilitation remains possible. In other words, a long incapacitating sentence means confinement long enough to prevent a person assessed as highly dangerous from committing further violence in the community.", question_type: "applied", weight: 1.25, educational_content: "Assume that a validated risk assessment shows a continuing serious danger, humane prison conditions are maintained, and the sentence receives periodic review." },
  { id: 294, order: 294, axis: "F3", key: 1, text: "A person convicted of serious assault should receive a shorter custodial sentence followed by intensive restorative supervision when strong evidence shows that this reduces repeat violence more effectively. In other words, a custodial sentence is time in jail or prison; restorative supervision can include treatment, restitution, victim participation, close monitoring, and a safety plan after release.", question_type: "applied", weight: 1.25, educational_content: "Assume that strong comparative evidence shows the combined sentence protects the public at least as well as a longer prison term." },
  { id: 295, order: 295, axis: "F5", key: -1, text: "Elected legislatures should be able to overrule expert agencies on major policy choices, while courts intervene only when the override violates a clear constitutional rule. In other words, lawmakers could reverse an expert agency's major policy judgment, and courts would stop that reversal only when it clearly violates the constitution.", question_type: "applied", weight: 1.25, educational_content: "Assume that the expert agency remains responsible for technical implementation after the legislature makes the final policy choice." },
  { id: 296, order: 296, axis: "F4", key: -1, text: "A legislative majority should be able to delegate narrow, temporary emergency powers to an expert agency and bar courts from reviewing the agency's individual decisions during that period. In other words, lawmakers could temporarily give specialists final authority over individual emergency decisions and prevent immediate court review of those decisions.", question_type: "applied", weight: 1.25, educational_content: "Assume that the delegated powers are precisely defined, automatically expire, remain subject to legislative oversight, and courts may still review whether the agency exceeded the delegation after the emergency period." },
  { id: 297, order: 297, axis: "F7", key: -1, text: "Instead of overseas military action, government should rely on expanded domestic screening and surveillance to prevent attacks. In other words, the strategy avoids military force but accepts broader coercive prevention within the country.", question_type: "applied", weight: 1.25, educational_content: "Assume that the expanded screening and surveillance remain subject to ordinary domestic law, time limits, and oversight." },
  { id: 298, order: 298, axis: "C3", key: 1, text: "A country should reject both military retaliation and broad domestic surveillance after a foreign-sponsored attack, relying on ordinary criminal investigation and diplomacy. In other words, the country would respond through ordinary police investigation and diplomacy rather than either military force or exceptional domestic surveillance.", question_type: "applied", weight: 1.25, educational_content: "Assume that ordinary investigation is realistically capable of pursuing the responsible individuals, although it may provide less deterrence than force or exceptional surveillance." },
  { id: 299, order: 299, axis: "C8", key: 1, text: "Private firms should be free to deploy labor-saving automation once safety standards are met, without job-preservation quotas or public ownership requirements. In other words, job-preservation quotas require firms to retain a specified amount of human labor despite available automation.", question_type: "applied", weight: 1.25, educational_content: "Assume that independent evidence shows the automation meets applicable safety standards and workers receive whatever transition protections ordinary law requires." },
  { id: 300, order: 300, axis: "C8", key: 1, text: "Government should build and operate a national advanced-computing utility so access to powerful AI is not controlled by a few private firms. In other words, the government would own or operate large computing systems and allocate access under public rules instead of leaving the most powerful AI infrastructure to a few private companies.", question_type: "applied", weight: 1.25, educational_content: "Assume that the utility uses published access rules, protects sensitive information, and does not give government unrestricted control over private AI applications." },
  { id: 301, order: 301, axis: "C1", key: -1, text: "Major banks, electricity systems, and other essential industries should be publicly owned rather than controlled by private shareholders. In other words, society should place core economic infrastructure under public ownership instead of leaving control and profits mainly to private investors.", question_type: "applied", weight: 1.25, educational_content: "Assume that the enterprises would remain professionally managed, subject to public audits, and required to meet service and financial targets." },
  { id: 302, order: 302, axis: "C1", key: -1, text: "Government should use binding production and investment targets in major industries instead of relying primarily on market prices and private capital allocation. In other words, public planning should decide much of what is produced and financed in strategic sectors rather than letting markets make most of those choices.", question_type: "applied", weight: 1.25, educational_content: "Assume that the targets are enacted through ordinary democratic procedures and revised when shortages, waste, or changing needs become evident." },
  { id: 303, order: 303, axis: "C1", key: 1, text: "Most farms, factories, banks, and large businesses should remain privately owned rather than being owned collectively by the state or society. In other words, individuals and private investors should generally keep ownership and control of productive enterprises.", question_type: "applied", weight: 1.25, educational_content: "Assume that ordinary labor, antitrust, consumer-protection, safety, and environmental laws still apply." },
  { id: 304, order: 304, axis: "C1", key: 1, text: "It is legitimate for investors to earn substantial profits from capital they own even when they do not personally work in the business. In other words, supplying money and accepting investment risk can justify receiving profits apart from wages for labor.", question_type: "applied", weight: 1.25, educational_content: "Assume that the investment was lawful, the firm is not protected by corrupt favoritism, and workers receive the compensation required by law and contract." },
  { id: 305, order: 305, axis: "C2", key: -1, text: "Society should prevent individuals from accumulating fortunes large enough to create lasting private political and economic power. In other words, taxes or other rules should stop any one person from becoming extraordinarily wealthy, even when the wealth was acquired legally.", question_type: "applied", weight: 1.25, educational_content: "Assume that the policy leaves people able to become affluent and preserves ordinary retirement savings, homes, and small businesses." },
  { id: 306, order: 306, axis: "C2", key: -1, text: "Government should provide material reparations to descendants of groups subjected to state-backed slavery or comparable systematic dispossession. In other words, public money or assets should compensate descendants for major historical injustices whose effects continue across generations.", question_type: "applied", weight: 1.25, educational_content: "Assume that eligibility can be determined under clear rules and that the program is funded through general taxation rather than by identifying individual present-day wrongdoers." },
  { id: 307, order: 307, axis: "C2", key: 1, text: "People should be free to become billionaires when their wealth is acquired lawfully, even if the resulting inequality is extremely large. In other words, government should not impose a maximum fortune merely because one person becomes vastly richer than most others.", question_type: "applied", weight: 1.25, educational_content: "Assume that applicable taxes were paid and that the wealth did not come from fraud, theft, slavery, or a government-granted monopoly." },
  { id: 308, order: 308, axis: "C2", key: 1, text: "Individuals should be allowed to own multiple homes as investments and charge market rents even during a severe housing shortage. In other words, housing scarcity should not by itself remove an owner\u2019s right to buy rental property and set rent through voluntary agreements.", question_type: "applied", weight: 1.25, educational_content: "Assume that the properties meet health and safety codes and that tenants are not being deceived or unlawfully evicted." },
  { id: 309, order: 309, axis: "C3", key: -1, text: "Government may require vaccination during a highly lethal epidemic when voluntary uptake is insufficient to prevent widespread transmission. In other words, protecting the public can justify making vaccination legally mandatory during an extreme outbreak.", question_type: "applied", weight: 1.25, educational_content: "Assume that independent evidence shows the vaccine substantially reduces transmission and severe illness, serious side effects are rare, and medical exemptions are available." },
  { id: 310, order: 310, axis: "C3", key: -1, text: "Courts should be able to authorize short-term preventive detention when specific evidence shows that a person is preparing a mass-casualty attack but prosecutors cannot yet file ordinary charges. In other words, a person could be confined before a prosecutable crime is complete when the demonstrated danger is exceptionally serious and immediate.", question_type: "applied", weight: 1.25, educational_content: "Assume that a judge reviews the evidence promptly, the person has a lawyer, the order expires automatically, and the government must repeatedly justify any extension." },
  { id: 311, order: 311, axis: "C3", key: 1, text: "Law-abiding adults should generally be permitted to own commonly available semiautomatic firearms for lawful self-defense and recreation. In other words, government should not broadly prohibit ordinary civilians from owning these firearms merely because they can fire one round with each trigger pull.", question_type: "applied", weight: 1.25, educational_content: "Assume that purchasers pass a background check, follow secure-storage rules, and have no violent felony conviction or comparable legal disqualification." },
  { id: 312, order: 312, axis: "C3", key: 1, text: "Government should not require encrypted communication services to create a special access mechanism for law enforcement. In other words, private messages should remain technically unreadable to the provider and government rather than containing a built-in government-access key.", question_type: "applied", weight: 1.25, educational_content: "Assume that the access mechanism would also create some additional risk of misuse, theft, or exploitation by hostile actors." },
  { id: 313, order: 313, axis: "C4", key: -1, text: "A single national law should determine the basic legality of abortion rather than allowing states or provinces to adopt substantially different rules. In other words, the country should have one minimum legal framework for abortion instead of a patchwork based on where a person lives.", question_type: "applied", weight: 1.25, educational_content: "Assume that the national government has clear constitutional authority to enact and enforce the rule." },
  { id: 314, order: 314, axis: "C4", key: 1, text: "States or provinces should be free to set substantially different abortion laws even when the result is unequal access across the country. In other words, abortion policy should be decided regionally rather than forced into one national rule.", question_type: "applied", weight: 1.25, educational_content: "Assume that regional governments have constitutional authority over the issue and that adults remain legally free to travel between regions." },
  { id: 315, order: 315, axis: "C5", key: -1, text: "Civil marriage should be legally defined as a union between one man and one woman. In other words, same-sex couples would not receive the legal status called marriage, even if another legal partnership status were available.", question_type: "applied", weight: 1.25, educational_content: "Assume that the alternative status could provide many contractual benefits but would remain legally and symbolically distinct from marriage." },
  { id: 316, order: 316, axis: "C5", key: -1, text: "Public schools should normally notify parents when a minor asks staff to use a different gender identity, name, or pronouns at school. In other words, schools should not ordinarily keep a student\u2019s social gender transition secret from the student\u2019s parents.", question_type: "applied", weight: 1.25, educational_content: "Assume that school staff have no specific reason to believe notification would expose the student to abuse or immediate danger." },
  { id: 317, order: 317, axis: "C5", key: 1, text: "Adults should be able to change the sex or gender marker on government identification through a declaration of identity without proving medical transition. In other words, legal recognition should follow an adult\u2019s affirmed gender rather than require surgery, hormones, or a medical diagnosis.", question_type: "applied", weight: 1.25, educational_content: "Assume that identity-fraud laws remain enforceable and that separate, narrowly tailored biological-sex data may still be collected when medically or statistically necessary." },
  { id: 318, order: 318, axis: "C5", key: 1, text: "Consenting adults should be allowed to enter a legally recognized marriage involving more than two spouses. In other words, civil marriage law should permit plural marriages rather than require every marriage to contain exactly two adults.", question_type: "applied", weight: 1.25, educational_content: "Assume that every spouse is an adult who gives independent consent and that ordinary laws against coercion, abuse, fraud, and child marriage are strictly enforced." },
  { id: 319, order: 319, axis: "C6", key: -1, text: "Citizens should receive priority over noncitizens for scarce public housing and long-term welfare benefits when their levels of need are otherwise comparable. In other words, political membership should give citizens a stronger claim to limited public resources than equally needy noncitizens.", question_type: "applied", weight: 1.25, educational_content: "Assume that emergency medical care, disaster relief, and basic protection from starvation or exposure remain available regardless of citizenship." },
  { id: 320, order: 320, axis: "C6", key: -1, text: "People who knowingly remain in a country without legal permission should normally be deported even after living and working there for many years. In other words, long residence and community ties should not usually defeat the country\u2019s right to enforce its immigration rules.", question_type: "applied", weight: 1.25, educational_content: "Assume that each person receives an individual hearing, is not being returned to persecution or torture, and has no separate legal claim to remain." },
  { id: 321, order: 321, axis: "C6", key: 1, text: "A child born in a country should normally receive citizenship at birth regardless of the immigration status of the parents. In other words, children should begin as full members of the society where they are born rather than inherit their parents\u2019 lack of legal status.", question_type: "applied", weight: 1.25, educational_content: "Assume that the usual narrow exception for children of foreign diplomats remains in place." },
  { id: 322, order: 322, axis: "C6", key: 1, text: "People should generally be free to live and work in another country when they pass reasonable security and identity checks. In other words, birthplace should not by itself prevent peaceful people from joining another society and labor market.", question_type: "applied", weight: 1.25, educational_content: "Assume that governments may phase admissions when necessary to maintain basic administrative capacity but may not exclude people merely because of ethnicity or religion." },
  { id: 323, order: 323, axis: "C7", key: -1, text: "A country with functioning independent courts should not allow an international criminal court to prosecute its citizens without national consent. In other words, final criminal authority over citizens should remain with the country\u2019s own legal system rather than an external court.", question_type: "applied", weight: 1.25, educational_content: "Assume that domestic courts are genuinely capable of investigating senior military and political leaders rather than shielding them automatically." },
  { id: 324, order: 324, axis: "C7", key: 1, text: "Countries should accept binding international prosecution of genocide, war crimes, and crimes against humanity even when national leaders object. In other words, an independent international court should be able to prosecute the gravest offenses when national power would otherwise block accountability.", question_type: "applied", weight: 1.25, educational_content: "Assume that the court has clearly defined jurisdiction, independent judges, meaningful defense rights, and review procedures." },
  { id: 325, order: 325, axis: "C8", key: -1, text: "Implantable brain-computer interfaces for elective cognitive enhancement should remain prohibited until long-term neurological and security risks are well understood. In other words, people should not yet receive implanted devices merely to improve memory or mental performance when the lasting risks remain uncertain.", question_type: "applied", weight: 1.25, educational_content: "Assume that the prohibition does not cover medically necessary devices used to restore lost movement, speech, hearing, or vision." },
  { id: 326, order: 326, axis: "C8", key: 1, text: "Adults should be allowed to use nonheritable gene editing to enhance traits such as strength, endurance, or resistance to disease once safety is established. In other words, regulated biotechnology should be available not only to treat illness but also to improve healthy adult capabilities.", question_type: "applied", weight: 1.25, educational_content: "Assume that the genetic changes affect only the consenting adult, are not passed to children, and have passed demanding independent safety review." },
  { id: 327, order: 327, axis: "C9", key: -1, text: "Government may approve a major fossil-fuel project when it is the most practical way to provide affordable and reliable energy, even if it causes substantial ecological and climate harm. In other words, urgent human energy needs can outweigh serious environmental damage when cleaner alternatives are not yet practical at the required scale.", question_type: "applied", weight: 1.25, educational_content: "Assume that the project complies with pollution controls, but its remaining greenhouse-gas emissions and habitat impacts are still significant." },
  { id: 328, order: 328, axis: "C9", key: 1, text: "Highly sentient animals should have legal rights that can block profitable human uses causing severe suffering. In other words, some animals should be treated as holders of enforceable interests rather than only as property whose welfare humans may choose to protect.", question_type: "applied", weight: 1.25, educational_content: "Assume that the protected category is limited by strong scientific evidence of advanced cognition and capacity for suffering." },
  { id: 329, order: 329, axis: "C10", key: -1, text: "Before fetal viability, a competent adult has an objective moral right to end a pregnancy regardless of local religious or cultural opposition. In other words, early abortion can be protected by a moral right to bodily autonomy that remains valid even when a society strongly rejects it.", question_type: "applied", weight: 1.25, educational_content: "Assume that the decision is voluntary and medically informed, the pregnancy is pre-viability, and the procedure is performed under ordinary medical safety rules." },
  { id: 330, order: 330, axis: "C10", key: -1, text: "Deliberately ending a healthy viable pregnancy for nonmedical reasons is objectively wrong regardless of the pregnant person\u2019s beliefs or the surrounding culture. In other words, once a fetus could survive outside the womb, personal or cultural approval cannot by itself make an elective late abortion morally acceptable.", question_type: "applied", weight: 1.25, educational_content: "Assume that continuing the pregnancy does not pose a serious threat to the pregnant person\u2019s life or long-term health and that safe delivery care is available." },
  { id: 331, order: 331, axis: "C10", key: 1, text: "Whether abortion early in pregnancy is morally permissible should largely be left to the pregnant person because reasonable moral traditions disagree about fetal status. In other words, early abortion may not have one culture-independent moral answer that government can confidently impose on everyone.", question_type: "applied", weight: 1.25, educational_content: "Assume that the procedure occurs before fetal viability and that the decision is voluntary and medically informed." },
  { id: 332, order: 332, axis: "C10", key: 1, text: "A society may legitimately prohibit most elective abortions when its moral tradition regards fetal life as part of the community\u2019s duties, even if other societies permit them. In other words, a restrictive abortion rule can be morally valid within one historical and cultural tradition without proving that every society must adopt the same rule.", question_type: "applied", weight: 1.25, educational_content: "Assume that the law contains exceptions for serious threats to life or long-term health and that the political process remains open to peaceful disagreement and reform." },
  { id: 333, order: 333, axis: "C11", key: -1, text: "Protecting innocent human life should always take priority over bodily autonomy when the two values directly conflict in abortion law. In other words, if the fetus counts as innocent human life, its protection should outrank the pregnant person\u2019s control over the pregnancy.", question_type: "applied", weight: 1.25, educational_content: "Assume that exceptions remain available when pregnancy creates a serious threat to the pregnant person\u2019s life or long-term health." },
  { id: 334, order: 334, axis: "C11", key: 1, text: "Abortion disputes can involve genuine values on both sides, so no single principle should automatically decide every case. In other words, fetal life, bodily autonomy, health, equality, and family circumstances may all matter without one value always defeating the others.", question_type: "applied", weight: 1.25, educational_content: "Assume that the legal system may still establish clear presumptions and limits while recognizing exceptional cases." },
  { id: 335, order: 335, axis: "F1", key: -1, text: "Even when policing and prisons produce serious injustice, reform should proceed through staged changes rather than abolishing and rebuilding the institutions at once. In other words, fixing rules, oversight, staffing, and incentives step by step is safer than replacing the whole system in one rupture.", question_type: "applied", weight: 1.25, educational_content: "Assume that existing institutions still comply with court orders and that reforms can be independently measured and enforced." },
  { id: 336, order: 336, axis: "F1", key: 1, text: "A society with persistently abusive policing and incarceration may need to abolish and replace those institutions rather than continue incremental reform. In other words, when repeated reforms fail, creating fundamentally different public-safety institutions can be justified despite major disruption.", question_type: "applied", weight: 1.25, educational_content: "Assume that multiple audited reform efforts have failed and that a concrete replacement plan provides emergency response, investigation, due process, and protection from violence." },
  { id: 337, order: 337, axis: "F2", key: -1, text: "A certified election result should be accepted after independent audits and court review even when the losing candidate continues to allege fraud. In other words, verified procedures should outweigh unsupported claims from a political leader who rejects the outcome.", question_type: "applied", weight: 1.25, educational_content: "Assume that observers from competing parties had access, material claims were examined publicly, and no evidence capable of changing the result was found." },
  { id: 338, order: 338, axis: "F2", key: 1, text: "Claims from major news organizations and government agencies should be independently verified rather than receiving a presumption of reliability. In other words, institutional reputation alone should not be enough when powerful organizations make important factual claims.", question_type: "applied", weight: 1.25, educational_content: "Assume that independent evidence and source records can reasonably be examined without exposing an individual to immediate danger." },
  { id: 339, order: 339, axis: "F3", key: -1, text: "The death penalty should remain available for exceptionally aggravated murder. In other words, some murders are so serious that execution can be a deserved punishment rather than merely a way to prevent future harm.", question_type: "applied", weight: 1.25, educational_content: "Assume that guilt is supported by multiple independent forms of evidence, the defendant received competent counsel, and automatic appeals have been exhausted." },
  { id: 340, order: 340, axis: "F3", key: -1, text: "A person who repeatedly sexually abuses a child deserves a severe prison sentence even when treatment could substantially reduce the risk of reoffending. In other words, punishment may be required because of the gravity of the wrong, not only because confinement is needed for public safety.", question_type: "applied", weight: 1.25, educational_content: "Assume that guilt is established through a fair process and that treatment can still occur during and after the sentence." },
  { id: 341, order: 341, axis: "F3", key: 1, text: "A person convicted of nonviolent drug distribution should ordinarily receive treatment and supervised reintegration rather than a long prison sentence. In other words, reducing addiction, repairing harm, and preventing future offending should matter more than imposing years of confinement for its own sake.", question_type: "applied", weight: 1.25, educational_content: "Assume that the offense did not involve violence, threats, trafficking of minors, or deliberate distribution of a substance represented falsely as something safer." },
  { id: 342, order: 342, axis: "F3", key: 1, text: "Even some people convicted of murder should have a realistic possibility of release after decades in prison if they demonstrate profound rehabilitation and no longer pose a serious danger. In other words, accountability for murder need not always require imprisonment until death when genuine change can be shown.", question_type: "applied", weight: 1.25, educational_content: "Assume that release requires an independent risk assessment, a public hearing, consideration of victims\u2019 views, and strict supervision." },
  { id: 343, order: 343, axis: "F4", key: -1, text: "A democratic majority should be able to authorize race-conscious university admissions even when courts interpret general equal-treatment guarantees to forbid them. In other words, elected majorities should usually decide whether public universities may consider race rather than judges deriving a nationwide ban from broad equality language.", question_type: "applied", weight: 1.25, educational_content: "Assume that the policy is public, limited in duration, periodically reviewed, and does not use rigid racial quotas." },
  { id: 344, order: 344, axis: "F4", key: 1, text: "Courts should invalidate race-conscious university admissions that violate constitutional equal-treatment rights even when a clear democratic majority supports the policy. In other words, an individual constitutional right to equal treatment can properly block a popular affirmative-action program.", question_type: "applied", weight: 1.25, educational_content: "Assume that the court applies the same legal standard to comparable racial classifications and explains why less restrictive alternatives are insufficient." },
  { id: 345, order: 345, axis: "F5", key: -1, text: "Elected lawmakers, not medical regulators, should have the final authority to decide whether puberty blockers or sex hormones used for gender transition may be prescribed to minors. In other words, because treatment of minors involves moral, parental, and developmental judgments, elected representatives should set the controlling rule after hearing medical advice.", question_type: "applied", weight: 1.25, educational_content: "Assume that regulators publish accurate evidence about benefits, uncertainties, side effects, and alternatives but do not claim expertise over every moral or family-policy question." },
  { id: 346, order: 346, axis: "F5", key: 1, text: "Independent medical regulators should set evidence-based eligibility and safety standards governing the use of puberty blockers or sex hormones for gender transition in minors even when elected officials face strong public pressure to prohibit them. In other words, trained specialists should decide which patients may receive treatment under clinical safeguards rather than allowing political majorities to impose a blanket medical rule.", question_type: "applied", weight: 1.25, educational_content: "Assume that the standards require age-appropriate consent, parental involvement except where lawfully waived for safety, careful screening, disclosure of uncertainty, and long-term monitoring." },
  { id: 347, order: 347, axis: "F6", key: -1, text: "The country\u2019s annual legal immigration level should be set through a binding national referendum rather than left primarily to the legislature. In other words, citizens should vote directly on how many immigrants may be admitted instead of delegating that major choice to representatives.", question_type: "applied", weight: 1.25, educational_content: "Assume that the referendum clearly states the proposed admission level and separately preserves treaty-based refugee protection and emergency humanitarian duties." },
  { id: 348, order: 348, axis: "F6", key: 1, text: "Legal immigration levels should be set through elected legislatures after hearings and amendment rather than by a single nationwide referendum. In other words, representatives should negotiate categories, labor needs, family rules, and enforcement details instead of asking voters to accept or reject one fixed number.", question_type: "applied", weight: 1.25, educational_content: "Assume that proceedings are public, proposals can be amended, agencies publish implementation data, and lawmakers face regular elections." },
  { id: 349, order: 349, axis: "F7", key: -1, text: "After a nuclear attack on an ally, leaders should seek a ceasefire and use nonnuclear responses rather than retaliate with nuclear weapons. In other words, avoiding further nuclear escalation should take priority even when an alliance partner has suffered a devastating attack.", question_type: "applied", weight: 1.25, educational_content: "Assume that conventional military, economic, diplomatic, and defensive options remain available, although none can fully undo the attack." },
  { id: 350, order: 350, axis: "F7", key: 1, text: "A country should be willing to use nuclear weapons first when conventional defeat would otherwise threaten its survival as an independent state. In other words, nuclear first use can be justified as a last resort even when the adversary has not yet used nuclear weapons.", question_type: "applied", weight: 1.25, educational_content: "Assume that leaders have strong evidence of the existential threat, ordinary conventional options are failing, and any use would still risk massive civilian harm and escalation." },
]
